window.I18N = {"uz":{"nav_home":"Bosh sahifa","nav_services":"Xizmatlar","nav_about":"Biz haqimizda","nav_blog":"Blog","nav_contact":"Aloqa","nav_contact_btn":"Bog'lanish","service1_title":"Korporativ huquq","service2_title":"Mehnat huquqi","service3_title":"Soliq Huquqi","service_ip_title":"Intellektual Mulk","service_out_title":"Yuridik Hamrohlik","service6_title":"Litsenziya va ruxsatnomalar","service1_desc":"Kompaniya tuzish va reestrdan o'tkazish, korporativ boshqaruv, aktsiyadorlik kelishuvlari, kompaniya qayta tashkil etish, kompaniyani tugatish.","service2_desc":"Mehnat shartnomalari, mehnat nizolari, ishdan bo'shatish masalalari, ichki hujjatlar ishlab chiqish, xodimlar huquqlari himoyasi.","service3_desc":"Soliq rejalashtirish, soliq hisoboti tayyorlash, soliq organlari bilan ishlash, soliq imtiyozlaridan foydalanish.","service_ip_desc":"Brend va mualliflik huquqini himoya qilish.","service_out_desc":"Biznes uchun doimiy yuridik ko'mak","service6_desc":"Turli faoliyat turlari uchun litsenziya olish, ruxsatnomalar, sertifikatlar, davlat ro'yxatidan o'tkazish va boshqa ruxsat etilgan faoliyat bilan bog'liq huquqiy xizmatlar.","service_ins_title":"To'lovga qobiliyatsizlik","service_ins_desc":"Jismoniy va yuridik shaxslarni to'lovga qobiliyatsiz deb topish, qarzlarni qayta tuzish, sanatsiya, tugatish tartib-taomillari va kreditorlar bilan ishlash bo'yicha to'liq huquqiy hamrohlik.","service_fam_title":"Oila huquqi","service_fam_desc":"Nikohdan ajratish, er-xotin mol-mulkini bo'lish, aliment, bolalar bilan bog'liq nizolar, meros, vasiyatnoma va nikoh shartnomasi bo'yicha huquqiy xizmatlar.","service_itp_title":"IT Park rezidentligi","service_itp_desc":"IT Park rezidentligi maqomini olish, soliq imtiyozlarini qo'llash, eksport shartnomalari, IT Visa va dasturiy mahsulotlarni huquqiy himoya qilish bo'yicha xizmatlar.","home:hero_title":"Professional Yuridik Xizmatlar","home:hero_desc":"Bizning tajribali yuristlarimiz sizning huquqlaringizni himoya qilish va biznesingizni rivojlantirishda yordam beradi.","home:hero_btn":"Konsultatsiya olish","home:services_title":"Bizning Xizmatlar","home:services_desc":"Biz kompaniyangizga kerakli bo'lgan barcha yuridik xizmatlarni taklif etamiz","more_btn":"Batafsil","home:contact_title":"Bog'lanish","home:contact_desc":"Biz bilan bog'laning va biz sizga yuridik maslahat beramiz","home:contact_info":"Aloqa ma'lumotlari","contact_address":"Toshkent shahri, Yunusobod tumani, Markaz 4, Abdulla Qodiriy ko'chasi 28A","home:social_media":"Ijtimoiy tarmoqlar","home:name_placeholder":"Ismingiz","home:email_placeholder":"Email manzilingiz","home:phone_placeholder":"Telefon raqamingiz","home:message_placeholder":"Xabaringiz","home:send_btn":"Xabar yuborish","msg_success":"Xabaringiz yuborildi!","msg_error":"Xatolik yuz berdi.","footer_desc":"Bizning yuridik kompaniya mijozlarimizning barcha huquqiy ehtiyojlarini qondirish uchun sifatli xizmatlarni taqdim etadi.","services_footer":"Xizmatlar","home:service1_footer":"Korporativ huquq","home:service2_footer":"Mehnat huquqi","home:service3_footer":"Soliq huquqi","home:service6_footer":"Litsenziya va ruxsatnomalar","links_footer":"Foydali havolalar","blog_footer":"Blog","about_footer":"Biz haqimizda","contact_footer":"Aloqa","rights_text":"Barcha huquqlar himoyalangan.","about:about_title":"Biz Haqimizda","about:about_desc":"VeroLex Advisory - tadbirkorlar va biznes egalari uchun ishonchli yuridik hamkoringiz","about:about_subtitle":"Biznes Egalari Uchun Maxsus Yondashuv","about:about_text1":"VeroLex Advisory 2020-yildan beri O'zbekistondagi tadbirkorlar va biznes egalariga yuqori sifatli yuridik xizmatlar ko'rsatib kelmoqda. Bizning asosiy maqsadimiz - biznesingizning huquqiy xavfsizligini ta'minlash va uning barqaror rivojlanishiga yordam berish.","about:about_text2":"Bizning yuristlarimiz biznes jarayonlarini chuqur tushunadigan va har bir mijozning muammosiga individual yondashadigan mutaxassislardan iborat. Biz nafaqat huquqiy masalalarni hal qilamiz, balki biznesingizning o'sishi va rivojlanishiga yordam beradigan strategik maslahatlarni ham taklif etamiz.","about:why_us_title":"Nima uchun bizni tanlash kerak?","about:why_us_subtitle":"Biznes egalari uchun maxsus yechimlar va afzalliklar","about:feat1_title":"Maxsus Yondashuv","about:feat1_desc":"Bizning yuristlarimiz biznes egalarining muammolarini chuqur tushunishlari va ularga mos yechimlarni taklif etishlari bilan ajralib turadi.","about:feat2_title":"Biznes Rivoji","about:feat2_desc":"Biz nafaqat huquqiy masalalarni hal qilamiz, balki biznesingizning o'sishi va rivojlanishiga yordam beradigan strategiyalarni ham taklif etamiz.","about:feat3_title":"Tez va Samarali","about:feat3_desc":"Biznes jarayonlari tez sur'atda bo'lganligi sababli, biz ham tezkor va samarali yuridik xizmat ko'rsatishga e'tibor qaratamiz.","about:feat4_title":"Xavflardan Himoya","about:feat4_desc":"Biznesingizni huquqiy xavflardan himoya qilish va kelajakdagi muammolarning oldini olish bo'yicha professional maslahatlar beramiz.","about:feat5_title":"Uzoq Muddatli Hamkorlik","about:feat5_desc":"Biznesingizning barcha bosqichlarida sizga yuridik qo'llab-quvvatlashni ta'minlaymiz va uzoq muddatli ishonchli hamkorlikni qadrlaymiz.","about:feat6_title":"Qulay Narxlar","about:feat6_desc":"Biznes egalari uchun maxsus tariflar va to'lov rejalari taklif etamiz, bu sizning moliyaviy imkoniyatlaringizga mos keladi.","blog:blog_title":"Blog va Ko'p So'raladigan Savollar","blog:blog_desc":"Yuridik sohadagi eng muhim savollarga javoblar","blog:faq_title":"Savol va Javoblar","blog:faq_subtitle":"Mijozlarimiz tomonidan eng ko'p beriladigan 18 ta savolga javob","blog:faq1_q":"MCHJ ochish uchun nimalar kerak va qancha vaqt ketadi?","blog:faq1_a":"Ta'sischilar pasporti nusxasi, firma nomi va ustav fondi miqdori kerak. Davlat xizmatlari orqali onlayn ro'yxatdan o'tish 30 daqiqadan 24 soatgacha vaqt oladi.","blog:faq2_q":"Ustav kapitalining eng kam miqdori qancha?","blog:faq2_a":"Hozirgi qonunchilikda MCHJ uchun ustav kapitalining eng kam miqdori belgilanmagan. Ta'sischilar o'zlari xohlagan summani (masalan, 1 mln so'm) belgilashlari mumkin.","blog:faq3_q":"Xodimni sinov muddati bilan ishga olish tartibi qanday?","blog:faq3_a":"Yangi Mehnat kodeksiga ko'ra, sinov muddati 3 oydan oshmasligi kerak (ayrim rahbarlar uchun 6 oy). Sinov muddati shartnomada aniq ko'rsatilishi shart.","blog:faq4_q":"Xodim ishdan bo'shamoqchi bo'lsa, qancha oldin aytishi kerak?","blog:faq4_a":"Xodim o'z xohishi bilan bo'shash haqida ish beruvchini kamida 14 kalendar kun oldin yozma ravishda ogohlantirishi lozim.","blog:faq5_q":"Aylanmadan olinadigan soliq stavkasi hozir necha foiz?","blog:faq5_a":"Umumiy qoida bo'yicha 4% ni tashkil qiladi. Lekin chekka hududlarda joylashgan yoki maxsus toifadagi tadbirkorlar uchun 1% gacha pasaytirilgan stavkalar mavjud.","blog:faq6_q":"QQS to'lovchisi bo'lish qachon majburiy bo'ladi?","blog:faq6_a":"Agar korxonaning yillik aylanmasi 1 milliard so'mdan oshsa, u avtomatik ravishda Qo'shilgan Qiymat Solig'i (QQS) va foyda solig'i to'lovchisiga aylanadi.","blog:faq7_q":"Brendni (Logotip) ro'yxatdan o'tkazish qancha vaqt oladi?","blog:faq7_a":"Adliya vazirligi huzuridagi agentlik orqali standart jarayon 7-8 oy davom etadi. Tezlashtirilgan tartibda esa 1-2 oy ichida guvohnoma olish mumkin.","blog:faq8_q":"Mualliflik huquqini himoya qilish uchun nima qilish kerak?","blog:faq8_a":"Mualliflik huquqi asar yaratilishi bilan paydo bo'ladi. Lekin nizolarni oldini olish uchun asarni Milliy depozitariyga joylashtirish (deponentlash) tavsiya etiladi.","blog:faq9_q":"Yuridik autsorsing nima degani?","blog:faq9_a":"Bu kompaniyangizda doimiy yurist saqlash o'rniga, yuridik firmaga murojaat qilib, oylik to'lov evaziga barcha huquqiy xizmatlarni olishdir. Bu arzonroq va sifatliroq bo'ladi.","blog:faq10_q":"Yuridik xizmat narxlari qanday belgilanadi?","blog:faq10_a":"Narxlar ish hajmi va murakkabligiga qarab kelishiladi. Bizda soatbay to'lov, bir martalik xizmat yoki oylik abonent to'lovi (autsorsing) mavjud.","blog:faq11_q":"Qurilish litsenziyasini olish uchun nimalar talab qilinadi?","blog:faq11_a":"Maxsus texnikalar, malakali muhandislar, ofis va ISO sertifikatlari talab qilinadi. Jarayon 'Shaffof Qurilish' tizimi orqali reyting yig'ishga asoslangan.","blog:faq12_q":"O'quv markazi ochish uchun litsenziya shartmi?","blog:faq12_a":"Ha, nodavlat ta'lim xizmatlarini ko'rsatish faoliyati litsenziyalanishi shart. Hujjatlar Ta'lim inspeksiyasiga topshiriladi.","blog:faq13_q":"Jismoniy shaxs qarzlarini qonuniy hisobdan chiqarishi mumkinmi?","blog:faq13_a":"Ha. «To'lovga qobiliyatsizlik to'g'risida»gi Qonunga muvofiq, majburiyatlar uch oy ichida bajarilmagan va qarz bazaviy hisoblash miqdorining 200 baravaridan kam bo'lmasa, sudga murojaat qilish mumkin.","blog:faq14_q":"Dastlabki maslahat bepulmi?","blog:faq14_a":"Ha, telefon orqali yoki Telegramda qisqa umumiy savollarga javob berish bepul. Hujjatlarni o'rganish va chuqur tahlil qilish pullik xizmatdir.","blog:faq15_q":"Viloyatlardan turib xizmatdan foydalansa bo'ladimi?","blog:faq15_a":"Albatta. Biz butun O'zbekiston bo'ylab onlayn (Zoom, Telegram, E-mail) xizmat ko'rsatamiz. Hujjatlar elektron imzo orqali rasmiylashtiriladi.","contact:contact_hero_title":"Bog'lanish","contact:contact_hero_desc":"Savollaringiz bormi? Biz bilan bog'laning!","contact:contact_info_title":"Aloqa ma'lumotlari","contact:label_address":"Manzil:","contact:text_address":"Toshkent shahri, Yunusobod tumani, Markaz 4, Abdulla Qodiriy ko'chasi 28A","contact:label_phone":"Telefon:","contact:label_email":"Email:","contact:social_title":"Ijtimoiy tarmoqlar","contact:form_title":"Xabar yuborish","contact:label_name":"Ismingiz","contact:ph_name":"Ismingizni kiriting","contact:label_phone_input":"Telefon raqam","contact:ph_phone":"+998","contact:label_message":"Xabar","contact:ph_message":"Xabaringizni yozing...","contact:btn_send":"Yuborish","contact:footer_services_title":"Xizmatlar","contact:footer_links_title":"Foydali havolalar","contact:footer_contact_title":"Aloqa","contact:footer_address_text":"Toshkent shahri, Yunusobod tumani, Markaz 4, Abdulla Qodiriy ko'chasi 28A","contact:footer_rights":"Barcha huquqlar himoyalangan.","korp:corp_title":"Korporativ Huquq","korp:corp_desc":"Kompaniya tuzish va biznesni samarali boshqarish uchun huquqiy yechimlar","korp:corp_main_title":"Biznesingiz uchun mustahkam poydevor","korp:corp_main_desc":"Korporativ huquq — har qanday biznesning asosi. Biz kompaniyalarni ro'yxatdan o'tkazishdan tortib, murakkab korporativ nizolarni hal qilishgacha bo'lgan barcha bosqichlarda professional yordam beramiz.","korp:srv1_t":"Kompaniya Tuzish","korp:srv1_d":"Yangi kompaniya tuzish, filial ochish, barcha huquqiy hujjatlarni tayyorlash va davlat organlarida ro'yxatdan o'tkazish.","korp:srv2_t":"Korporativ Boshqaruv","korp:srv2_d":"Aktsiyadorlik kelishuvlari, direktorlar kengashi qarorlari, aktsiyadorlar yig'ilishi va boshqaruv organlarining faoliyati.","korp:srv3_t":"Shartnomalar","korp:srv3_d":"Turli xil shartnomalarni (sotish-xarid, xizmat ko'rsatish, hamkorlik va boshqalar) tuzish, tahrirlash va huquqiy maslahat berish.","korp:srv4_t":"Qayta Tashkil Etish","korp:srv4_d":"Kompaniyani birlashtirish, bo'lish, qayta tashkil etish va likvidatsiya qilish bo'yicha huquqiy xizmatlar.","korp:srv5_t":"Huquqiy Ekspertiza","korp:srv5_d":"Mavjud shartnomalarni huquqiy jihatdan tekshirish, kamchiliklarni aniqlash va ularni bartaraf etish bo'yicha maslahat xizmatlari.","korp:srv6_t":"Nizolarni Hal Qilish","korp:srv6_d":"Aksiyadorlar, direktorlar va boshqaruv organlari o'rtasidagi nizolarni hal qilish bo'yicha huquqiy yordam.","other_services":"Boshqa Xizmatlar","korp:footer_address_text":"Toshkent shahri, Yunusobod tumani, Markaz 4, Abdulla Qodiriy ko'chasi 28A","korp:footer_rights":"Barcha huquqlar himoyalangan.","meh:labor_title":"Mehnat Huquqi","meh:labor_desc":"Xodimlar va ish beruvchilar o'rtasidagi munosabatlarni tartibga solish","meh:labor_main_title":"Mehnat munosabatlarida qonun ustuvorligi","meh:labor_main_desc":"Biz ish beruvchilar va xodimlar o'rtasidagi munosabatlarni huquqiy jihatdan tartibga solish, nizolarni hal qilish va kadrlar hujjatlarini yuritishda professional yordam beramiz.","meh:srv1_t":"Mehnat Shartnomalari","meh:srv1_d":"Mehnat shartnomalarini tuzish, tahrirlash va ularning qonuniyligini tekshirish.","meh:srv2_t":"Mehnat Nizolari","meh:srv2_d":"Mehnat nizolarini sud va sudgacha bo'lgan tartibda hal etishda yuridik yordam.","meh:srv3_t":"Kadrlar Hujjatlari","meh:srv3_d":"Kadrlar hujjatlarini yuridik jihatdan to'g'ri tuzish va ularni qayta ko'rib chiqish.","meh:srv4_t":"Mehnat Qonunchiligi","meh:srv4_d":"Mehnat qonunchiligi talablariga rioya etilishini monitoring qilish va maslahat berish.","meh:footer_address_text":"Toshkent shahri, Yunusobod tumani, Markaz 4, Abdulla Qodiriy ko'chasi 28A","meh:footer_rights":"Barcha huquqlar himoyalangan.","tax:tax_title":"Soliq Huquqi","tax:tax_desc":"Moliyaviy barqarorlik va soliq xavfsizligini ta'minlash","tax:tax_main_title":"Soliq xatarlarini minimallashtirish","tax:tax_main_desc":"Bizning tajribali soliq maslahatchilarimiz kompaniyangizni ortiqcha soliq to'lovlaridan himoya qiladi va moliyaviy faoliyatingizni qonuniy optimallashtirishga yordam beradi.","tax:srv1_t":"Soliq Rejalashtirish","tax:srv1_d":"Kompaniyangiz uchun samarali soliq rejalarini ishlab chiqish va qonuniy yo'llar bilan soliq yukini kamaytirish.","tax:srv2_t":"Soliq Hisoboti","tax:srv2_d":"Barcha soliq deklaratsiyalarini va hisobotlarini vaqtida va to'g'ri tayyorlash.","tax:srv3_t":"Soliq Organlari bilan Muloqot","tax:srv3_d":"Soliq tekshiruvlari va boshqa masalalar bo'yicha soliq organlari bilan vakillik qilish.","tax:srv4_t":"Soliq Tahlili","tax:srv4_d":"Kompaniyangiz soliq majburiyatlarini tahlil qilish va ularni optimallashtirish bo'yicha takliflar berish.","ip:ip_title":"Intellektual Mulk Huquqi","ip:ip_desc":"G'oyalaringiz va brendingizni ishonchli himoya qilish","ip:ip_main_title":"Innovatsiyalar va Ijod Himoyasi","ip:ip_main_desc":"Biz intellektual mulk obyektlarini ro'yxatdan o'tkazish, himoya qilish va tijoratlashtirish bo'yicha to'liq xizmatlar spektrini taklif etamiz. Sizning g'oyalaringiz – sizning kapitalingizdir.","ip:srv1_t":"Tovar Belgilari","ip:srv1_d":"Brendingizni himoya qilish uchun tovar belgisi va xizmat ko'rsatish belgilarini davlat ro'yxatidan o'tkazish.","ip:srv2_t":"Mualliflik Huquqi","ip:srv2_d":"Ilmiy, adabiy va badiiy asarlarga bo'lgan mualliflik huquqlarini himoya qilish va deponentlash.","ip:srv3_t":"Ixtirolarni Patentlash","ip:srv3_d":"Ixtirolar, foydali modellar va sanoat namunalari uchun patent olishda ko'maklashish.","ip:srv4_t":"IP Audit va Strategiya","ip:srv4_d":"Kompaniyangizning intellektual mulk portfelini tahlil qilish va uni boshqarish strategiyasini ishlab chiqish.","ip:srv5_t":"Litsenziya va Franchayzing","ip:srv5_d":"Intellektual mulk obyektlaridan foydalanish bo'yicha litsenziya va franchayzing shartnomalarini tuzish.","ip:srv6_t":"Nizolarni Hal Qilish","ip:srv6_d":"Intellektual mulk sohasidagi huquqbuzarliklar va kontrafakt mahsulotlarga qarshi kurashish bo'yicha yuridik yordam.","ip:footer_address_text":"Toshkent shahri, Yunusobod tumani, Markaz 4, Abdulla Qodiriy ko'chasi 28A","ip:footer_rights":"Barcha huquqlar himoyalangan.","out:out_title":"Yuridik Hamrohlik","out:out_desc":"Biznesingiz uchun professional va doimiy huquqiy ko'mak (Autsorsing)","out:out_main_title":"Shtatdagi yuristdan afzalroq yechim","out:out_main_desc":"Yuridik autsorsing — bu kompaniyangizning barcha huquqiy masalalarini tashqi professional jamoaga ishonib topshirishdir. Bu nafaqat tejamkor, balki xavfsizroq va samaraliroq.","out:srv1_t":"Doimiy Maslahat","out:srv1_d":"Biznes faoliyatingiz davomida yuzaga keladigan har qanday huquqiy savollar bo'yicha 24/7 tezkor maslahatlar.","out:srv2_t":"Shartnomalar bilan Ishlash","out:srv2_d":"Barcha turdagi shartnomalarni tuzish, huquqiy ekspertizadan o'tkazish va xatarlarni oldini olish.","out:srv3_t":"Sud Vakilligi","out:srv3_d":"Iqtisodiy, fuqarolik va ma'muriy sudlarda kompaniya manfaatlarini professional himoya qilish.","out:srv4_t":"Ichki Hujjatlar","out:srv4_d":"Buyruqlar, nizomlar, yo'riqnomalar va boshqa ichki korporativ hujjatlarni qonunchilikka muvofiq tayyorlash.","out:srv5_t":"Muzokaralar","out:srv5_d":"Hamkorlar va kontragentlar bilan bo'ladigan uchrashuvlarda ishtirok etish va manfaatlaringizni himoya qilish.","out:srv6_t":"Huquqiy Audit","out:srv6_d":"Kompaniyaning mavjud hujjatlarini tahlil qilish va aniqlangan kamchiliklarni bartaraf etish.","out:footer_address_text":"Toshkent shahri, Yunusobod tumani, Markaz 4, Abdulla Qodiriy ko'chasi 28A","out:footer_rights":"Barcha huquqlar himoyalangan.","lic:lic_title":"Litsenziya va Ruxsatnomalar","lic:lic_desc":"Biznesingiz uchun zarur bo'lgan barcha ruxsatnomalarni qonuniy rasmiylashtirish","lic:lic_main_title":"Davlat organlari bilan oson hamkorlik","lic:lic_main_desc":"Murakkab byurokratik jarayonlarni bizga topshiring. Biz litsenziyalash va ruxsat berish jarayonlarining barcha bosqichlarida sizga ko'maklashamiz.","lic:srv1_t":"Litsenziya olish","lic:srv1_d":"Turli faoliyat turlari uchun litsenziya olish bo'yicha to'liq yuridik xizmat. Davlat organlari bilan muloqot va hujjatlarni tayyorlash.","lic:srv2_t":"Ruxsatnomalar","lic:srv2_d":"Qurilish, import-export, sog'liqni saqlash va boshqa sohalar uchun ruxsatnomalar olish. Barcha jarayonlarni biz qo'llab-quvvatlaymiz.","lic:srv3_t":"Litsenziyani yangilash","lic:srv3_d":"Mavjud litsenziya va ruxsatnomalarni yangilash va ularni muddatiga uzaytirish. Vaqtida yangilash uchun eslatma xizmati.","lic:footer_address_text":"Toshkent shahri, Yunusobod tumani, Markaz 4, Abdulla Qodiriy ko'chasi 28A","lic:footer_rights":"Barcha huquqlar himoyalangan.","ex_hero_eyebrow":"Yuridik konsalting — Toshkent","ex_btn_services":"Xizmatlarimiz","ex_stat1":"Amaliyot yo'nalishi","ex_stat2":"Tezkor maslahat","ex_stat3":"Xizmat ko'rsatish tili","ex_stat4":"Onlayn — butun O'zbekiston bo'ylab","ex_btn_faq":"Barcha savol-javoblar","ex_label_email":"Email (ixtiyoriy)","ex_form_hint":"Maydonlarni to'ldiring — mutaxassislarimiz tez orada siz bilan bog'lanadi.","msg_fill":"Iltimos, ism va telefon raqamini kiriting.","ex_cta_t":"Huquqiy masalangizni bugun hal qilishni boshlang","ex_cta_d":"Dastlabki qisqa maslahat — bepul. Biz bilan o'zingizga qulay usulda bog'laning.","ex_side_t":"Savolingiz bormi?","ex_side_d":"Mutaxassislarimiz ushbu yo'nalish bo'yicha batafsil maslahat beradi.","ex_call":"Qo'ng'iroq qiling","ex_write":"Yozing","ex_addr_t":"Manzil","ex_social_t":"Ijtimoiy tarmoqlar","ex_about_pre":"Biz haqimizda","ex_faq_pre":"Savol-javob","ex_contact_pre":"Aloqa","ex_svc_pre":"Xizmatlar","blog:faq16_q":"Nikohdan ajratish uchun albatta sudga borish kerakmi?","blog:faq16_a":"Yo'q. Er-xotin o'zaro rozi bo'lsa, voyaga yetmagan farzandlari bo'lmasa va mulkiy nizo bo'lmasa, nikoh FHDYo organida bekor qilinadi. Aks holda ish sudda ko'riladi.","blog:faq17_q":"Merosni qabul qilish uchun necha oy vaqt beriladi?","blog:faq17_a":"Merosga bo'lgan huquq to'g'risidagi guvohnoma meros ochilgan kundan olti oy o'tgach beriladi. Shu muddat ichida notariusga murojaat qilish lozim; muddat uzrli sabab bilan o'tkazilgan bo'lsa, sud orqali tiklanadi.","blog:faq18_q":"IT Park rezidenti bo'lish uchun nima qilish kerak?","blog:faq18_a":"Avval O'zbekistonda yuridik shaxs ro'yxatdan o'tkaziladi, so'ng IT Parkning rasmiy portali orqali elektron raqamli imzo yordamida ariza topshiriladi. Faoliyat turi ruxsat etilgan ro'yxatga mos bo'lishi shart.","ex_process_pre":"Jarayon","ins:ins_title":"To'lovga Qobiliyatsizlik","ins:ins_desc":"Jismoniy va yuridik shaxslarning to'lovga qobiliyatsizligi bo'yicha professional huquqiy yordam","ins:ins_main_title":"Qarz yukidan qonuniy chiqish yo'li","ins:ins_main_desc":"To'lovga qobiliyatsizlik — bu faoliyatning tugashi emas, balki qonun beradigan qayta boshlash imkoniyatidir. Biz 2022-yil 12-apreldagi O'RQ-763-son «To'lovga qobiliyatsizlik to'g'risida»gi Qonun asosida qarzdorlar va kreditorlar manfaatlarini sud tartib-taomilining barcha bosqichlarida himoya qilamiz.","ins:note_t":"Huquqiy asos","ins:note_d":"O'zbekiston Respublikasining 2022-yil 12-apreldagi O'RQ-763-son «To'lovga qobiliyatsizlik to'g'risida»gi Qonuni, Iqtisodiy protsessual kodeks hamda Oliy sud Plenumining tegishli qarorlari. Har bir vaziyat alohida tahlil qilinadi va yakuniy natija ish holatlariga bog'liq.","ins:srv1_t":"Yuridik shaxslar to'lovga qobiliyatsizligi","ins:srv1_d":"Korxonaga nisbatan to'lovga qobiliyatsizlik to'g'risida ish qo'zg'atish, kuzatuv, sud sanatsiyasi, tashqi boshqaruv va tugatish tartib-taomillarida vakillik qilish.","ins:srv2_t":"Jismoniy shaxslar to'lovga qobiliyatsizligi","ins:srv2_d":"Fuqarolarning bank kreditlari va boshqa qarzlari bo'yicha sudga ariza tayyorlash hamda qarzni tarkibiy jihatdan o'zgartirish rejasini ishlab chiqish.","ins:srv3_t":"Kreditorlar manfaatlarini himoya qilish","ins:srv3_d":"Talablarni kreditorlar reyestriga kiritish, kreditorlar yig'ilishida ishtirok etish va qarzni undirish bo'yicha huquqiy strategiya tuzish.","ins:srv4_t":"Sanatsiya va murosa bitimi","ins:srv4_d":"Korxonani moliyaviy sog'lomlashtirish rejasini tayyorlash, kreditorlar bilan murosa bitimini kelishish va uni sudda tasdiqlash.","ins:srv5_t":"Bitimlarni bekor qilish va javobgarlik","ins:srv5_d":"Qarzdorning shubhali bitimlarini haqiqiy emas deb topish, rahbar va ta'sischilarning subsidiar javobgarligi bo'yicha ishlar.","ins:srv6_t":"Yakka tartibdagi tadbirkorlar","ins:srv6_d":"YTT maqomidagi qarzdorlar uchun tartib-taomilning o'ziga xos xususiyatlarini hisobga olgan holda to'liq huquqiy hamrohlik.","ins:steps_t":"Ish qanday olib boriladi","ins:steps_d":"To'rt bosqichli aniq va shaffof jarayon","ins:step1_t":"Moliyaviy tahlil","ins:step1_d":"Qarz tarkibi, aktivlar va to'lovga qobiliyatsizlik alomatlari baholanadi.","ins:step2_t":"Hujjatlarni tayyorlash","ins:step2_d":"Sudga ariza, ilova hujjatlar va dalillar bazasi shakllantiriladi.","ins:step3_t":"Sudda vakillik","ins:step3_d":"Tartib-taomilning barcha bosqichlarida manfaatlaringiz himoya qilinadi.","ins:step4_t":"Yakuniy natija","ins:step4_d":"Qarzlar qayta tuziladi yoki hisobdan chiqariladi, tartib-taomil yakunlanadi.","ins:faq_t":"Ko'p so'raladigan savollar","ins:faq_d":"To'lovga qobiliyatsizlik yo'nalishi bo'yicha eng ko'p beriladigan savollar","ins:faq1_q":"Jismoniy shaxs qachon to'lovga qobiliyatsiz deb topilishi mumkin?","ins:faq1_a":"Qarzdor pul majburiyatlarini uch oy ichida bajarmagan va qarz summasi bazaviy hisoblash miqdorining 200 baravaridan kam bo'lmagan taqdirda sudga murojaat qilish mumkin. Har bir holat hujjatlar asosida alohida baholanadi.","ins:faq2_q":"Yuridik shaxs uchun to'lovga qobiliyatsizlik alomatlari qanday?","ins:faq2_a":"Qonunda ikki alomat nazarda tutilgan: vaqtincha to'lovga qobiliyatsizlik — majburiyatni uch oy ichida bajara olmaslik (shaharni tashkil etuvchi va unga tenglashtirilgan korxonalar uchun olti oy); doimiy to'lovga qobiliyatsizlik — qarzdor majburiyatlarining aktivlari qiymatidan oshib ketishi.","ins:faq3_q":"Qanday tartib-taomillar qo'llaniladi?","ins:faq3_a":"Yuridik shaxsga nisbatan kuzatuv, sud sanatsiyasi, tashqi boshqaruv, tugatish tartib-taomili va murosa bitimi qo'llanilishi mumkin. Jismoniy shaxsga nisbatan esa qarzni tarkibiy jihatdan o'zgartirish rejasi, mol-mulkni sotish tartib-taomili va murosa bitimi qo'llaniladi.","ins:faq4_q":"Ish qaysi sudda ko'rib chiqiladi?","ins:faq4_a":"Yuridik shaxsga nisbatan ish uning davlat ro'yxatidan o'tgan joydagi sudda, jismoniy shaxs va yakka tartibdagi tadbirkorga nisbatan esa yashash joyidagi sudda Iqtisodiy protsessual kodeks qoidalari bo'yicha ko'rib chiqiladi.","ins:faq5_q":"Tartib-taomilda barcha mol-mulk olib qo'yiladimi?","ins:faq5_a":"Yo'q. Qonunchilikda undiruv qaratilishi mumkin bo'lmagan mol-mulk ro'yxati belgilangan va u tartib-taomil doirasida hisobga olinadi. Garovga qo'yilgan mol-mulkka nisbatan alohida qoidalar amal qiladi — vaziyat har bir ish bo'yicha alohida tahlil qilinishi lozim.","ins:faq6_q":"Soxta to'lovga qobiliyatsizlik uchun javobgarlik bormi?","ins:faq6_a":"Ha. Qasddan yoki soxta to'lovga qobiliyatsizlikka yo'l qo'yganlik uchun ma'muriy va jinoiy javobgarlik nazarda tutilgan. Bundan tashqari, korxona rahbari hamda ta'sischilariga nisbatan subsidiar javobgarlik qo'llanilishi mumkin.","fam:fam_title":"Oila Huquqi","fam:fam_desc":"Nikoh, ajrim, aliment, bolalar, mol-mulk va meros masalalarida ishonchli huquqiy yordam","fam:fam_main_title":"Oilaviy masalalarda tinch va adolatli yechim","fam:fam_main_desc":"Oilaviy nizolar har doim shaxsiy va nozik masalalardir. Biz O'zbekiston Respublikasi Oila kodeksi va Fuqarolik kodeksi normalariga tayangan holda, mijozning va eng avvalo bolalarning manfaatlarini himoya qilib, imkon qadar sudgacha kelishuvga erishishga intilamiz.","fam:note_t":"Huquqiy asos","fam:note_d":"O'zbekiston Respublikasining Oila kodeksi, Fuqarolik kodeksi (V bo'lim — «Vorislik huquqi»), Fuqarolik protsessual kodeksi hamda Oliy sud Plenumining nikohdan ajratish va meros huquqiga oid qarorlari. Maslahat har bir oilaning aniq holatidan kelib chiqib beriladi.","fam:srv1_t":"Nikohdan ajratish","fam:srv1_d":"Nikohni FHDYo organlari yoki sud tartibida bekor qilish, da'vo arizasini tayyorlash va sud majlislarida vakillik qilish.","fam:srv2_t":"Mol-mulkni bo'lish","fam:srv2_d":"Er-xotinning umumiy mol-mulkini bo'lish, shaxsiy mulkni ajratib olish va kelishuv bitimini rasmiylashtirish.","fam:srv3_t":"Aliment masalalari","fam:srv3_d":"Alimentni ulush yoki qat'iy summada undirish, miqdorini o'zgartirish hamda qarzdorlikni undirish bo'yicha yordam.","fam:srv4_t":"Bolalar bilan bog'liq nizolar","fam:srv4_d":"Bolaning kim bilan yashashi, ikkinchi ota-ona bilan muloqot tartibi, otalikni belgilash va farzandlikka olish masalalari.","fam:srv5_t":"Meros va vorislik","fam:srv5_d":"Merosni qabul qilishni rasmiylashtirish, muddatni tiklash, majburiy ulush va merosxo'rlar o'rtasidagi nizolar.","fam:srv6_t":"Vasiyatnoma va nikoh shartnomasi","fam:srv6_d":"Vasiyatnoma va nikoh shartnomasini tuzish, notarial tasdiqlash hamda ularni sudda haqiqiy emas deb topish bo'yicha ishlar.","fam:steps_t":"Biz qanday ishlaymiz","fam:steps_d":"Nozik masalalarda ehtiyotkor va bosqichma-bosqich yondashuv","fam:step1_t":"Maxfiy suhbat","fam:step1_d":"Vaziyatni tinglaymiz, hujjatlarni ko'rib chiqamiz va real istiqbolni tushuntiramiz.","fam:step2_t":"Sudgacha kelishuv","fam:step2_d":"Imkoniyat bo'lsa, taraflar o'rtasida kelishuvga erishishga harakat qilamiz.","fam:step3_t":"Sudda himoya","fam:step3_d":"Kelishuv bo'lmasa, da'vo tayyorlanadi va manfaatlaringiz sudda himoya qilinadi.","fam:step4_t":"Rasmiylashtirish","fam:step4_d":"Qaror FHDYo yoki notariusda rasmiylashtiriladi va ijro etilishi nazorat qilinadi.","fam:faq_t":"Ko'p so'raladigan savollar","fam:faq_d":"Oila huquqi yo'nalishi bo'yicha eng ko'p beriladigan savollar","fam:faq1_q":"Nikoh qaysi hollarda FHDYo orqali bekor qilinadi?","fam:faq1_a":"Er-xotin o'zaro rozi bo'lsa, voyaga yetmagan umumiy farzandlari bo'lmasa va mulkiy talab yoki ta'minot masalasida nizo bo'lmasa, nikoh FHDYo organida bekor qilinadi. Aks holda ish sud tartibida ko'riladi.","fam:faq2_q":"Aliment miqdori qanday belgilanadi?","fam:faq2_a":"Ota-ona o'rtasida kelishuv bo'lmasa, sud oylik ish haqi va boshqa daromadning bir farzand uchun 1/4, ikki farzand uchun 1/3, uch va undan ortiq farzand uchun 1/2 qismini undiradi. Har bir bola uchun undiriladigan miqdor qonunchilikda belgilangan eng kam ish haqining 26,5 foizidan kam bo'lmasligi lozim.","fam:faq3_q":"Er-xotinning umumiy mol-mulki qanday bo'linadi?","fam:faq3_a":"Nikoh davrida orttirilgan mol-mulk umumiy hisoblanadi va odatda teng ulushlarda bo'linadi. Sud voyaga yetmagan bolalar manfaatlarini yoki e'tiborga loyiq boshqa holatlarni hisobga olib teng ulushdan chetga chiqishi mumkin. Nikohgacha tegishli bo'lgan, meros yoki hadya tariqasida olingan mulk shaxsiy mulk hisoblanadi.","fam:faq4_q":"Merosni qabul qilish muddati qancha?","fam:faq4_a":"Merosga bo'lgan huquq to'g'risidagi guvohnoma meros ochilgan kundan e'tiboran olti oy o'tgach beriladi. Shu muddat ichida notariusga murojaat qilish lozim. Muddat uzrli sabab bilan o'tkazib yuborilgan bo'lsa, uni sud tartibida tiklash mumkin.","fam:faq5_q":"Vasiyatnoma bo'lsa ham majburiy ulush olish mumkinmi?","fam:faq5_a":"Ha. Vasiyat qoldiruvchining voyaga yetmagan yoki mehnatga qobiliyatsiz bolalari, mehnatga qobiliyatsiz er yoki xotini hamda ota-onasi vasiyatnoma mazmunidan qat'i nazar merosdan majburiy ulush olish huquqiga ega.","fam:faq6_q":"Aliment to'lamaslik qanday oqibatlarga olib keladi?","fam:faq6_a":"Qarzdorlik majburiy ijro tartibida undiriladi, ijrochi tomonidan mol-mulk va hisobvaraqlarga cheklov qo'yilishi hamda chet elga chiqish vaqtincha taqiqlanishi mumkin. Uzoq muddat to'lamaslik ma'muriy va jinoiy javobgarlikka olib kelishi mumkin.","itp:itp_title":"IT Park Rezidentligi","itp:itp_desc":"IT kompaniyalar uchun rezidentlik maqomi, soliq imtiyozlari va eksport faoliyatini huquqiy rasmiylashtirish","itp:itp_main_title":"IT biznesingiz uchun imtiyozli huquqiy maydon","itp:itp_main_desc":"IT Park rezidentligi O'zbekistondagi texnologiya kompaniyalariga sezilarli soliq va bojxona imtiyozlarini beradi. Biz faoliyat turini to'g'ri tanlashdan tortib, ariza topshirish, shartnoma tuzish va rezidentlik davomidagi hisobot majburiyatlarigacha bo'lgan barcha bosqichlarda hamrohlik qilamiz.","itp:note_t":"Muhim eslatma","itp:note_d":"Imtiyozlar amaldagi Soliq kodeksi va IT Park faoliyatini tartibga soluvchi Prezident farmonlari hamda hukumat qarorlari bilan belgilanadi va vaqti-vaqti bilan yangilanib turadi. Aniq stavkalar, muddatlar va ruxsat etilgan faoliyat turlari ro'yxati murojaat sanasidagi tahrirga muvofiq tekshiriladi.","itp:srv1_t":"Rezidentlik maqomini olish","itp:srv1_d":"Biznes-rejani tayyorlash, arizani rasmiylashtirish va IT Park direksiyasi bilan rezident faoliyati shartnomasini tuzish.","itp:srv2_t":"Kompaniya tuzish va faoliyat turi","itp:srv2_d":"MChJ yoki boshqa shaklda ro'yxatdan o'tkazish hamda ruxsat etilgan faoliyat turlari ro'yxatiga mos kodni to'g'ri tanlash.","itp:srv3_t":"Soliq imtiyozlari va hisobot","itp:srv3_d":"Imtiyozlarni qonuniy qo'llash, choraklik hisobotlarni topshirish tartibi va soliq risklarini oldindan baholash.","itp:srv4_t":"Eksport va valyuta operatsiyalari","itp:srv4_d":"Xorijiy mijozlar bilan shartnomalar, IT xizmatlari eksportini rasmiylashtirish va valyuta tushumi bo'yicha maslahatlar.","itp:srv5_t":"IT Visa va xorijiy mutaxassislar","itp:srv5_d":"Xorijiy ta'sischilar va mutaxassislar uchun viza, ro'yxatdan o'tish hamda mehnat munosabatlarini rasmiylashtirish.","itp:srv6_t":"Dasturiy mahsulotlarni himoya qilish","itp:srv6_d":"Mualliflik huquqi, tovar belgisi, NDA, litsenziya va autsorsing shartnomalari orqali IT mahsulotini huquqiy mustahkamlash.","itp:steps_t":"Rezidentlikka yo'l","itp:steps_d":"To'rt bosqichda tayyorgarlikdan doimiy hamrohlikkacha","itp:step1_t":"Faoliyatni baholash","itp:step1_d":"Biznes-modelingiz ruxsat etilgan faoliyat turlariga mosligi tekshiriladi.","itp:step2_t":"Kompaniyani rasmiylashtirish","itp:step2_d":"Yuridik shaxs tuziladi yoki mavjud hujjatlar talablarga moslashtiriladi.","itp:step3_t":"Ariza va shartnoma","itp:step3_d":"Ariza portal orqali topshiriladi va rezident shartnomasi imzolanadi.","itp:step4_t":"Doimiy hamrohlik","itp:step4_d":"Hisobot, shartnomalar va imtiyozlarni saqlab qolish bo'yicha yordam beriladi.","itp:faq_t":"Ko'p so'raladigan savollar","itp:faq_d":"IT Park rezidentligi bo'yicha eng ko'p beriladigan savollar","itp:faq1_q":"Rezidentlar qanday soliq imtiyozlariga ega?","itp:faq1_a":"Rezidentlar uchun foyda solig'i, aylanmadan olinadigan soliq va ijtimoiy soliq bo'yicha nol stavka belgilangan, xodimlarning daromad solig'i esa 7,5 foizni tashkil qiladi. Shuningdek, o'z ehtiyoji uchun keltiriladigan ayrim uskunalar bo'yicha bojxona imtiyozlari amal qiladi. Aniq stavkalar va amal qilish muddatlari amaldagi tahrir bo'yicha tekshiriladi.","itp:faq2_q":"Ariza qayerga va qanday topshiriladi?","itp:faq2_a":"Kompaniya O'zbekistonda yuridik shaxs sifatida ro'yxatdan o'tganidan so'ng, ariza IT Parkning rasmiy portali orqali elektron raqamli imzo yordamida onlayn topshiriladi. Arizaga biznes-reja va ta'sis hujjatlari ilova qilinadi.","itp:faq3_q":"Har qanday IT kompaniya rezident bo'la oladimi?","itp:faq3_a":"Yo'q. Rezidentlik faqat qonunchilikda belgilangan ruxsat etilgan faoliyat turlari ro'yxatiga kiruvchi kompaniyalarga beriladi. Kompyuter yoki texnologiya bilan bog'liq har qanday biznes avtomatik ravishda bu ro'yxatga kirmaydi, shu sababli faoliyat turini oldindan tekshirish zarur.","itp:faq4_q":"Kompaniya Toshkentda joylashishi shartmi?","itp:faq4_a":"Yo'q. Rezidentlik maqomi va u bilan bog'liq imtiyozlar O'zbekistonning istalgan hududida ro'yxatdan o'tgan kompaniyalarga nisbatan amal qiladi — jismonan Toshkentda bo'lish talab etilmaydi.","itp:faq5_q":"Rezidentning qanday majburiyatlari bor?","itp:faq5_a":"Rezident IT Park bilan tuzilgan faoliyat shartlari to'g'risidagi shartnoma majburiyatlariga rioya etishi va o'z faoliyati to'g'risida har chorakda ma'lumot taqdim etishi lozim. Majburiyatlar bajarilmasa, maqom va imtiyozlar to'xtatilishi mumkin.","itp:faq6_q":"Xorijiy ta'sischi va mutaxassislar uchun qanday imkoniyatlar bor?","itp:faq6_a":"Xorijiy mutaxassislar uchun maxsus viza rejimi, dividend va ish haqini chet el valyutasida to'lash imkoniyati hamda xorijiy kompaniyalarni qo'llab-quvvatlash dasturlari nazarda tutilgan. Har bir dastur shartlari alohida tekshirilishi lozim.","ex_map_open":"Xaritada ochish","ex_map_route":"Yo'nalish olish","ex_note_t":"Huquqiy asos","ex_steps_t":"Ish jarayoni","ex_steps_d":"To'rt bosqichda aniq va shaffof hamkorlik","ex_faq_t":"Ko'p so'raladigan savollar","ex_faq_d":"Ushbu yo'nalish bo'yicha eng ko'p beriladigan savollar","ex_geo_t":"Bizning ofisimiz","ex_geo_d":"Toshkent shahri markazida, Yunusobod tumanida joylashganmiz","korp:note_d":"O'zbekiston Respublikasining Fuqarolik kodeksi, «Mas'uliyati cheklangan hamda qo'shimcha mas'uliyatli jamiyatlar to'g'risida»gi va «Aksiyadorlik jamiyatlari va aksiyadorlarning huquqlarini himoya qilish to'g'risida»gi qonunlar, shuningdek «Tadbirkorlik faoliyati erkinligining kafolatlari to'g'risida»gi Qonun.","korp:step1_t":"Biznes-modelni tahlil qilish","korp:step1_d":"Faoliyat turi, tashkiliy-huquqiy shakl va ta'sischilar tarkibi baholanadi.","korp:step2_t":"Ta'sis hujjatlarini tayyorlash","korp:step2_d":"Ustav, ta'sis shartnomasi va ishtirokchilar qarorlari qonunchilikka muvofiq tuziladi.","korp:step3_t":"Davlat ro'yxatidan o'tkazish","korp:step3_d":"Hujjatlar davlat xizmatlari portali orqali topshiriladi va guvohnoma olinadi.","korp:step4_t":"Faoliyatni yo'lga qo'yish","korp:step4_d":"Bank hisobvarag'i, ERI, ichki hujjatlar va soliq hisobiga qo'yish rasmiylashtiriladi.","korp:pfaq1_q":"MChJ ochish qancha vaqt oladi?","korp:pfaq1_a":"Hujjatlar to'liq va to'g'ri bo'lsa, davlat ro'yxatidan o'tkazish elektron tarzda 30 daqiqadan bir ish kunigacha amalga oshiriladi. Vaqt asosan hujjatlarni oldindan tayyorlashga sarflanadi.","korp:pfaq2_q":"Ustav kapitalining eng kam miqdori belgilanganmi?","korp:pfaq2_a":"Mas'uliyati cheklangan jamiyat uchun qonunchilikda eng kam miqdor belgilanmagan — ta'sischilar uni mustaqil belgilaydi. Ayrim litsenziyalanadigan faoliyat turlari va moliya sektori uchun alohida talablar amal qiladi.","korp:pfaq3_q":"Xorijiy shaxs kompaniya ta'sis eta oladimi?","korp:pfaq3_a":"Ha. Xorijiy jismoniy va yuridik shaxslar O'zbekistonda kompaniya ta'sischisi bo'lishi mumkin. Xorijiy investitsiya ishtirokidagi korxonalar uchun ustav fondi va hujjatlarni rasmiylashtirishga nisbatan qo'shimcha talablar qo'llanilishi mumkin.","korp:pfaq4_q":"Direktorni almashtirish uchun nima qilinadi?","korp:pfaq4_a":"Ishtirokchilar (aksiyadorlar) yig'ilishining qarori qabul qilinadi, yangi rahbar bilan mehnat shartnomasi rasmiylashtiriladi va o'zgarish davlat reyestriga kiritiladi. Bank va ERI ma'lumotlari ham yangilanadi.","korp:pfaq5_q":"Kompaniyani tugatish qancha davom etadi?","korp:pfaq5_a":"Ixtiyoriy tugatish kreditorlarni xabardor qilish, hisob-kitoblarni yakunlash va soliq tekshiruvini o'z ichiga oladi. Amalda jarayon bir necha oy davom etadi va korxonaning majburiyatlari hajmiga bog'liq.","meh:note_d":"O'zbekiston Respublikasining amaldagi Mehnat kodeksi, Oliy sud Plenumining mehnat nizolariga oid qarorlari hamda mehnatga haq to'lash va ish vaqtiga oid hukumat qarorlari.","meh:step1_t":"Kadrlar hujjatlari auditi","meh:step1_d":"Mehnat shartnomalari, buyruqlar va ichki hujjatlar qonunchilikka muvofiqligi tekshiriladi.","meh:step2_t":"Kamchiliklarni bartaraf etish","meh:step2_d":"Aniqlangan xatolar tuzatiladi, yetishmayotgan hujjatlar ishlab chiqiladi.","meh:step3_t":"Sudgacha hal etish","meh:step3_d":"Nizo mehnat nizolari komissiyasi yoki muzokaralar orqali hal qilishga harakat qilinadi.","meh:step4_t":"Sudda vakillik","meh:step4_d":"Kelishuv bo'lmasa, da'vo tayyorlanadi va manfaatlaringiz sudda himoya qilinadi.","meh:pfaq1_q":"Sinov muddati eng ko'pi bilan qancha?","meh:pfaq1_a":"Umumiy qoidaga ko'ra sinov muddati uch oydan oshmaydi; ayrim toifadagi xodimlar uchun uzoqroq muddat belgilanishi mumkin. Sinov sharti mehnat shartnomasida aniq ko'rsatilishi shart, aks holda xodim sinovsiz qabul qilingan hisoblanadi.","meh:pfaq2_q":"Xodim bo'shashda necha kun oldin ogohlantiradi?","meh:pfaq2_a":"O'z xohishi bilan bo'shashda xodim ish beruvchini kamida ikki hafta — 14 kalendar kun oldin yozma ravishda ogohlantirishi lozim. Taraflar kelishuviga ko'ra shartnoma qisqaroq muddatda ham bekor qilinishi mumkin.","meh:pfaq3_q":"Noqonuniy bo'shatilgan bo'lsam qayerga murojaat qilaman?","meh:pfaq3_a":"Mehnat nizolari komissiyasiga yoki bevosita sudga murojaat qilish mumkin. Ishga tiklash to'g'risidagi talablar uchun qisqartirilgan murojaat muddati belgilangan, shu sababli kechiktirmasdan yuristga murojaat qilish muhim.","meh:pfaq4_q":"Ichki mehnat tartibi qoidalari majburiymi?","meh:pfaq4_a":"Ha. Ichki mehnat tartibi qoidalari, shtat jadvali va lavozim yo'riqnomalari har bir tashkilotda bo'lishi lozim. Ularning yo'qligi tekshiruvlarda ma'muriy javobgarlikka olib kelishi mumkin.","meh:pfaq5_q":"Masofaviy ish qanday rasmiylashtiriladi?","meh:pfaq5_a":"Masofaviy va to'liqsiz ish vaqti shartlari mehnat shartnomasida yoki unga qo'shimcha kelishuvda yozma ravishda belgilanadi. Ish vaqtini hisobga olish va mehnatga haq to'lash tartibi ham aniq ko'rsatilishi lozim.","tax:note_d":"O'zbekiston Respublikasining Soliq kodeksi, soliq imtiyozlariga oid Prezident farmonlari va hukumat qarorlari, shuningdek soliq organlarining rasmiy tushuntirishlari.","tax:step1_t":"Soliq holatini tahlil qilish","tax:step1_d":"Amaldagi soliq rejimi, hisobotlar va mavjud xatarlar baholanadi.","tax:step2_t":"Optimallashtirish rejasi","tax:step2_d":"Qonuniy imtiyozlar va rejimlardan foydalanish variantlari taklif etiladi.","tax:step3_t":"Hisobotni rasmiylashtirish","tax:step3_d":"Deklaratsiya va hisobotlar to'g'ri tuziladi hamda muddatida topshiriladi.","tax:step4_t":"Tekshiruvlarda himoya","tax:step4_d":"Soliq organlari bilan muloqot va zarur bo'lsa shikoyat hamda sud tartibida himoya.","tax:pfaq1_q":"Aylanmadan olinadigan soliq stavkasi qancha?","tax:pfaq1_a":"Umumiy stavka 4 foizni tashkil etadi. Ayrim hududlar, faoliyat turlari va tadbirkorlik toifalari uchun pasaytirilgan stavkalar nazarda tutilgan — aniq stavka faoliyat turingizga qarab belgilanadi.","tax:pfaq2_q":"QQS to'lovchisi bo'lish qachon majburiy?","tax:pfaq2_a":"Yillik aylanma qonunchilikda belgilangan chegaradan — bir milliard so'mdan oshganda korxona qo'shilgan qiymat solig'i va foyda solig'i to'lovchisiga o'tadi. Ixtiyoriy ravishda ham QQS to'lovchisi bo'lish mumkin.","tax:pfaq3_q":"Soliq tekshiruvi haqida oldindan xabar beriladimi?","tax:pfaq3_a":"Rejali tekshiruvlar belgilangan tartibda va oldindan xabardor qilingan holda o'tkaziladi. Tezkor va ko'ndalang tekshiruvlar uchun esa alohida asos va tartib nazarda tutilgan.","tax:pfaq4_q":"Soliq organi qarori ustidan shikoyat qilish mumkinmi?","tax:pfaq4_a":"Ha. Qaror ustidan yuqori turuvchi soliq organiga yoki bevosita sudga shikoyat qilish mumkin. Shikoyat berish muddatlariga qat'iy rioya qilish talab etiladi, aks holda huquq yo'qoladi.","tax:pfaq5_q":"Soliq qarzi uchun qanday choralar qo'llaniladi?","tax:pfaq5_a":"Qarz o'z vaqtida to'lanmasa, qonunchilikda nazarda tutilgan majburiy undirish choralari — jumladan hisobvaraq bo'yicha operatsiyalarni to'xtatib turish va mol-mulkka undiruv qaratish qo'llanilishi mumkin. Muddatida murojaat qilish orqali bunday oqibatlarning oldini olish mumkin.","ip:note_d":"«Tovar belgilari, xizmat ko'rsatish belgilari va tovar kelib chiqqan joy nomlari to'g'risida»gi, «Mualliflik huquqi va turdosh huquqlar to'g'risida»gi hamda «Ixtirolar, foydali modellar va sanoat namunalari to'g'risida»gi qonunlar, shuningdek Fuqarolik kodeksining tegishli normalari.","ip:step1_t":"Dastlabki qidiruv","ip:step1_d":"Belgi yoki yechimning ro'yxatga olinganlari bilan to'qnashuvi tekshiriladi.","ip:step2_t":"Zayavka tayyorlash","ip:step2_d":"Tavsif, tasvir va tovarlar hamda xizmatlar sinflari to'g'ri tanlanadi.","ip:step3_t":"Ekspertizadan o'tkazish","ip:step3_d":"Vakolatli organ so'rovlariga javob beriladi va e'tirozlar bartaraf etiladi.","ip:step4_t":"Guvohnoma va himoya","ip:step4_d":"Guvohnoma olinadi, muddati kuzatiladi va huquqbuzarliklarga qarshi chora ko'riladi.","ip:pfaq1_q":"Tovar belgisini ro'yxatdan o'tkazish qancha vaqt oladi?","ip:pfaq1_a":"Standart tartibda jarayon bir necha oy davom etadi va ekspertiza bosqichlariga bog'liq. Tezlashtirilgan ekspertizadan foydalanish imkoniyati mavjud bo'lib, u muddatni sezilarli qisqartiradi.","ip:pfaq2_q":"Ro'yxatdan o'tkazishdan oldin qidiruv shartmi?","ip:pfaq2_a":"Rasman shart emas, biroq oldindan qidiruv o'xshash belgilarni aniqlab, rad javobi va keyingi nizolar xavfini sezilarli darajada kamaytiradi. Biz uni har doim tavsiya etamiz.","ip:pfaq3_q":"Mualliflik huquqi ro'yxatdan o'tkaziladimi?","ip:pfaq3_a":"Mualliflik huquqi asar yaratilgan paytdan boshlab vujudga keladi va ro'yxatdan o'tkazishni talab qilmaydi. Ixtiyoriy deponentlash esa nizo yuzaga kelganda mualliflikni tasdiqlovchi dalil bo'lib xizmat qiladi.","ip:pfaq4_q":"Tovar belgisi necha yilga beriladi?","ip:pfaq4_a":"Tovar belgisiga bo'lgan huquq o'n yil muddatga beriladi va har safar shu muddatga cheklovsiz uzaytirilishi mumkin. Uzaytirish uchun muddat tugashidan oldin murojaat qilish lozim.","ip:pfaq5_q":"Belgim boshqalar tomonidan ishlatilsa nima qilaman?","ip:pfaq5_a":"Avval huquqbuzarlik hujjatlashtiriladi va huquqbuzarga da'vo xati yuboriladi. Natija bo'lmasa sudga murojaat qilinib, foydalanishni taqiqlash, kontrafakt mahsulotni muomaladan chiqarish va zararni undirish talab etiladi.","out:note_d":"Xizmat Fuqarolik kodeksining pullik xizmatlar ko'rsatishga oid normalari asosida shartnoma bilan rasmiylashtiriladi. Sudlarda vakillik Fuqarolik protsessual, Iqtisodiy protsessual va Ma'muriy sud ishlarini yuritish to'g'risidagi kodekslarga muvofiq amalga oshiriladi.","out:step1_t":"Huquqiy audit","out:step1_d":"Mavjud shartnomalar, ichki hujjatlar va xatarlar bir marta to'liq ko'rib chiqiladi.","out:step2_t":"Shartnoma va tarif","out:step2_d":"Ish hajmiga mos oylik tarif tanlanadi va xizmat shartnomasi imzolanadi.","out:step3_t":"Kundalik hamrohlik","out:step3_d":"Shartnomalar, buyruqlar va murojaatlar bo'yicha tezkor huquqiy yordam beriladi.","out:step4_t":"Hisobot va rivojlantirish","out:step4_d":"Bajarilgan ishlar bo'yicha hisobot beriladi va xatarlarni kamaytirish taklif etiladi.","out:pfaq1_q":"Autsorsing shtatdagi yuristdan nimasi bilan farq qiladi?","out:pfaq1_a":"Bitta yurist o'rniga turli yo'nalishlarga ixtisoslashgan jamoa ishlaydi: korporativ, mehnat, soliq va sud amaliyoti bo'yicha. Bunda ish haqi, soliq va ta'til bilan bog'liq xarajatlar bo'lmaydi.","out:pfaq2_q":"Shartnoma qanday muddatga tuziladi?","out:pfaq2_a":"Odatda bir yilga tuziladi va oylik to'lov asosida ishlaydi. Sinov uchun qisqaroq muddat ham kelishilishi mumkin; shartnomani bekor qilish tartibi hujjatda oldindan belgilanadi.","out:pfaq3_q":"Sudda kim vakillik qiladi?","out:pfaq3_a":"Fuqarolik, iqtisodiy va ma'muriy ishlarda ishonchnoma asosida bizning yuristlarimiz vakillik qiladi. Jinoyat ishlari bo'yicha himoya esa qonunga muvofiq faqat advokat maqomiga ega shaxs tomonidan amalga oshiriladi.","out:pfaq4_q":"Maxfiylik qanday ta'minlanadi?","out:pfaq4_a":"Shartnomaga maxfiylik sharti kiritiladi, zarur bo'lsa alohida NDA imzolanadi. Hujjatlar cheklangan doiradagi mas'ul xodimlarga beriladi va uchinchi shaxslarga oshkor qilinmaydi.","out:pfaq5_q":"Ish hajmi oshsa to'lov o'zgaradimi?","out:pfaq5_a":"Oylik tarif kelishilgan ish hajmini qamrab oladi. Sud jarayonlari yoki yirik bitimlar kabi qo'shimcha ishlar oldindan alohida kelishiladi — kutilmagan to'lovlar bo'lmaydi.","lic:note_d":"2021-yil 14-iyuldagi O'RQ-701-son «Litsenziyalash, ruxsat berish va xabardor qilish tartib-taomillari to'g'risida»gi Qonun, Prezidentning 2020-yil 24-avgustdagi PF-6044-son Farmoni hamda Vazirlar Mahkamasining tegishli yagona nizomlari.","lic:step1_t":"Tartib-taomilni aniqlash","lic:step1_d":"Faoliyatingiz litsenziya, ruxsatnoma yoki xabardor qilishni talab etishi aniqlanadi.","lic:step2_t":"Talablarga moslashtirish","lic:step2_d":"Xodimlar, bino, texnika va hujjatlar litsenziya talab va shartlariga moslashtiriladi.","lic:step3_t":"Onlayn ariza topshirish","lic:step3_d":"Ariza «Litsenziya» axborot tizimi yoki davlat xizmatlari portali orqali yuboriladi.","lic:step4_t":"Nazorat va uzaytirish","lic:step4_d":"Muddatlar kuzatiladi, qayta rasmiylashtirish va uzaytirish o'z vaqtida amalga oshiriladi.","lic:pfaq1_q":"Litsenziya, ruxsatnoma va xabardor qilish farqi nimada?","lic:pfaq1_a":"Bu uch xil tartib-taomil. Litsenziya eng qat'iy talablarni nazarda tutadi, ruxsatnoma soddaroq tartibda beriladi, xabardor qilishda esa faoliyatni boshlash uchun vakolatli organni xabardor qilishning o'zi kifoya.","lic:pfaq2_q":"Ariza qayerga topshiriladi?","lic:pfaq2_a":"Ariza «Litsenziya» axborot tizimi yoki Yagona interaktiv davlat xizmatlari portali orqali elektron raqamli imzo yordamida onlayn topshiriladi.","lic:pfaq3_q":"Litsenziya berishni rad etish asoslari qanday?","lic:pfaq3_a":"Qonunda uchta asosiy asos nazarda tutilgan: hujjatlarning to'liq bo'lmagan hajmda taqdim etilishi; talabgorning litsenziya talab va shartlariga muvofiq emasligi; taqdim etilgan hujjatlarda noto'g'ri yoki buzib ko'rsatilgan ma'lumotlarning mavjudligi.","lic:pfaq4_q":"Rad javobi ustidan shikoyat qilish mumkinmi?","lic:pfaq4_a":"Ha. Talabgor litsenziyalovchi organning qarori hamda uning mansabdor shaxslari harakati (harakatsizligi) ustidan belgilangan tartibda bevosita sudga shikoyat qilishga haqli.","lic:pfaq5_q":"Muddat tugaganda nima bo'ladi?","lic:pfaq5_a":"Muddati tugagan litsenziya asosida faoliyatni davom ettirish qonunga zid hisoblanadi va javobgarlikka olib keladi. Shu sababli uzaytirish uchun muddat tugashidan oldin murojaat qilish lozim."},"ru":{"nav_home":"Главная","nav_services":"Услуги","nav_about":"О нас","nav_blog":"Блог","nav_contact":"Контакты","nav_contact_btn":"Связаться","service1_title":"Корпоративное Право","service2_title":"Трудовое Право","service3_title":"Налоговое Право","service_ip_title":"Интеллектуальная Собственность","service_out_title":"Юридическое Сопровождение","service6_title":"Лицензии и Разрешения","service1_desc":"Создание и регистрация компании, корпоративное управление, акционерные соглашения, реорганизация, ликвидация.","service2_desc":"Трудовые договоры, споры, вопросы увольнения, разработка внутренних документов, защита прав сотрудников.","service3_desc":"Налоговое планирование, подготовка отчетов, работа с налоговыми органами, использование льгот.","service_ip_desc":"Защита бренда и авторских прав.","service_out_desc":"Постоянная юридическая поддержка бизнеса.","service6_desc":"Получение лицензий на виды деятельности, разрешений, сертификатов, государственная регистрация.","service_ins_title":"Неплатёжеспособность","service_ins_desc":"Признание физических и юридических лиц неплатёжеспособными, реструктуризация долгов, санация, ликвидационные процедуры и работа с кредиторами.","service_fam_title":"Семейное право","service_fam_desc":"Расторжение брака, раздел совместного имущества, алименты, споры о детях, наследство, завещание и брачный договор.","service_itp_title":"Резидентство IT Park","service_itp_desc":"Получение статуса резидента IT Park, применение налоговых льгот, экспортные контракты, IT Visa и правовая защита программных продуктов.","home:hero_title":"Профессиональные Юридические Услуги","home:hero_desc":"Наши опытные юристы помогут защитить ваши права и развивать бизнес.","home:hero_btn":"Получить консультацию","home:services_title":"Наши Услуги","home:services_desc":"Мы предлагаем все юридические услуги, необходимые вашей компании","more_btn":"Подробнее","home:contact_title":"Контакты","home:contact_desc":"Свяжитесь с нами для юридической консультации","home:contact_info":"Контактная информация","contact_address":"г. Ташкент, Юнусабадский район, Центр 4, ул. Абдуллы Кадыри 28А","home:social_media":"Социальные сети","home:name_placeholder":"Ваше имя","home:email_placeholder":"Ваш email","home:phone_placeholder":"Ваш телефон","home:message_placeholder":"Ваше сообщение","home:send_btn":"Отправить","msg_success":"Сообщение отправлено!","msg_error":"Ошибка.","footer_desc":"Наша юридическая компания предоставляет качественные услуги для удовлетворения всех правовых потребностей клиентов.","services_footer":"Услуги","home:service1_footer":"Корпоративное право","home:service2_footer":"Трудовое право","home:service3_footer":"Налоговое право","home:service6_footer":"Лицензии и разрешения","links_footer":"Полезные ссылки","blog_footer":"Блог","about_footer":"О нас","contact_footer":"Контакты","rights_text":"Все права защищены.","about:about_title":"О Нас","about:about_desc":"VeroLex Advisory - ваш надежный юридический партнер","about:about_subtitle":"Особый подход к владельцам бизнеса","about:about_text1":"VeroLex Advisory предоставляет высококачественные юридические услуги предпринимателям в Узбекистане с 2020 года. Наша главная цель - обеспечить правовую безопасность вашего бизнеса.","about:about_text2":"Наши юристы - эксперты, глубоко понимающие бизнес-процессы. Мы не только решаем правовые вопросы, но и предлагаем стратегические советы для роста вашего бизнеса.","about:why_us_title":"Почему выбирают нас?","about:why_us_subtitle":"Специальные решения и преимущества для бизнеса","about:feat1_title":"Особый подход","about:feat1_desc":"Наши юристы глубоко понимают проблемы владельцев бизнеса и предлагают подходящие решения.","about:feat2_title":"Развитие бизнеса","about:feat2_desc":"Мы помогаем не только с правовыми вопросами, но и со стратегиями роста вашего бизнеса.","about:feat3_title":"Быстро и эффективно","about:feat3_desc":"Мы уделяем внимание быстрому и эффективному предоставлению юридических услуг, так как бизнес требует скорости.","about:feat4_title":"Защита от рисков","about:feat4_desc":"Профессиональные консультации по защите бизнеса от правовых рисков и предотвращению проблем.","about:feat5_title":"Долгосрочное сотрудничество","about:feat5_desc":"Мы обеспечиваем юридическую поддержку на всех этапах вашего бизнеса и ценим надежное партнерство.","about:feat6_title":"Выгодные цены","about:feat6_desc":"Мы предлагаем специальные тарифы и планы оплаты, подходящие для ваших финансовых возможностей.","blog:blog_title":"Блог и Часто Задаваемые Вопросы","blog:blog_desc":"Ответы на самые важные юридические вопросы","blog:faq_title":"Вопросы и Ответы","blog:faq_subtitle":"Ответы на 18 самых частых вопросов наших клиентов","blog:faq1_q":"Что нужно для открытия ООО и сколько времени это занимает?","blog:faq1_a":"Нужны копии паспортов учредителей, название фирмы и размер уставного фонда. Регистрация онлайн через госуслуги занимает от 30 минут до 24 часов.","blog:faq2_q":"Каков минимальный размер уставного капитала?","blog:faq2_a":"В действующем законодательстве для ООО минимальный размер не установлен. Учредители могут определить любую сумму (например, 1 млн сумов).","blog:faq3_q":"Как оформить работника с испытательным сроком?","blog:faq3_a":"Согласно новому Трудовому кодексу, испытательный срок не должен превышать 3 месяцев (для руководителей - 6 месяцев). Это должно быть указано в договоре.","blog:faq4_q":"За сколько дней нужно предупредить об увольнении?","blog:faq4_a":"Работник обязан письменно предупредить работодателя о своем желании уволиться не менее чем за 14 календарных дней.","blog:faq5_q":"Какова сейчас ставка налога с оборота?","blog:faq5_a":"Общая ставка составляет 4%. Однако для предпринимателей в отдаленных районах или специальных категориях ставка может быть снижена до 1%.","blog:faq6_q":"Когда обязательно становиться плательщиком НДС?","blog:faq6_a":"Если годовой оборот предприятия превышает 1 миллиард сумов, оно автоматически становится плательщиком НДС и налога на прибыль.","blog:faq7_q":"Сколько времени занимает регистрация бренда (логотипа)?","blog:faq7_a":"Стандартный процесс через Агентство по интеллектуальной собственности занимает 7-8 месяцев. Ускоренная процедура - 1-2 месяца.","blog:faq8_q":"Как защитить авторские права?","blog:faq8_a":"Авторское право возникает с момента создания произведения. Однако для предотвращения споров рекомендуется депонировать произведение в Национальном депозитарии.","blog:faq9_q":"Что такое юридический аутсорсинг?","blog:faq9_a":"Это передача юридических вопросов внешней фирме вместо содержания штатного юриста. Это дешевле и качественнее.","blog:faq10_q":"Как определяются цены на услуги?","blog:faq10_a":"Цены зависят от объема и сложности работы. У нас есть почасовая оплата, разовые услуги или месячная подписка.","blog:faq11_q":"Что нужно для получения строительной лицензии?","blog:faq11_a":"Требуется спецтехника, квалифицированные инженеры, офис и сертификаты ISO. Процесс основан на наборе рейтинга в системе 'Шаффоф Курилиш'.","blog:faq12_q":"Нужна ли лицензия для учебного центра?","blog:faq12_a":"Да, деятельность негосударственных образовательных учреждений подлежит лицензированию Инспекцией по образованию.","blog:faq13_q":"Может ли физическое лицо законно списать долги?","blog:faq13_a":"Да. Согласно Закону «О неплатёжеспособности», обратиться в суд можно, если обязательства не исполнены в течение трёх месяцев, а долг составляет не менее 200-кратного размера базовой расчётной величины.","blog:faq14_q":"Бесплатна ли первичная консультация?","blog:faq14_a":"Да, краткие ответы на общие вопросы по телефону или в Telegram бесплатны. Изучение документов и глубокий анализ - платные.","blog:faq15_q":"Можно ли работать дистанционно из регионов?","blog:faq15_a":"Конечно. Мы предоставляем услуги онлайн по всему Узбекистану (Zoom, Telegram, E-mail). Документы подписываются через ЭЦП.","contact:contact_hero_title":"Контакты","contact:contact_hero_desc":"У вас есть вопросы? Свяжитесь с нами!","contact:contact_info_title":"Контактная информация","contact:label_address":"Адрес:","contact:text_address":"г. Ташкент, Юнусабадский район, Центр 4, ул. Абдуллы Кадыри 28А","contact:label_phone":"Телефон:","contact:label_email":"Email:","contact:social_title":"Социальные сети","contact:form_title":"Отправить сообщение","contact:label_name":"Ваше имя","contact:ph_name":"Введите ваше имя","contact:label_phone_input":"Номер телефона","contact:ph_phone":"+998","contact:label_message":"Сообщение","contact:ph_message":"Напишите ваше сообщение...","contact:btn_send":"Отправить","contact:footer_services_title":"Услуги","contact:footer_links_title":"Полезные ссылки","contact:footer_contact_title":"Контакты","contact:footer_address_text":"г. Ташкент, Юнусабадский район, Центр 4, ул. Абдуллы Кадыри 28А","contact:footer_rights":"Все права защищены.","korp:corp_title":"Корпоративное Право","korp:corp_desc":"Правовые решения для создания компании и эффективного управления бизнесом","korp:corp_main_title":"Надежный фундамент для вашего бизнеса","korp:corp_main_desc":"Корпоративное право — основа любого бизнеса. Мы оказываем профессиональную помощь на всех этапах: от регистрации компаний до разрешения сложных корпоративных споров.","korp:srv1_t":"Создание Компаний","korp:srv1_d":"Создание новых компаний, открытие филиалов, подготовка всех правовых документов и регистрация в госорганах.","korp:srv2_t":"Корпоративное Управление","korp:srv2_d":"Акционерные соглашения, решения совета директоров, собрания акционеров и деятельность органов управления.","korp:srv3_t":"Договоры","korp:srv3_d":"Составление, редактирование и правовое консультирование по различным договорам (купля-продажа, услуги, партнерство и др.).","korp:srv4_t":"Реорганизация","korp:srv4_d":"Юридические услуги по слиянию, разделению, реорганизации и ликвидации компаний.","korp:srv5_t":"Правовая Экспертиза","korp:srv5_d":"Правовая проверка действующих договоров, выявление недостатков и консультации по их устранению.","korp:srv6_t":"Разрешение Споров","korp:srv6_d":"Юридическая помощь в разрешении споров между акционерами, директорами и органами управления.","other_services":"Другие Услуги","korp:footer_address_text":"г. Ташкент, Юнусабадский район, Центр 4, ул. Абдуллы Кадыри 28А","korp:footer_rights":"Все права защищены.","meh:labor_title":"Трудовое Право","meh:labor_desc":"Регулирование отношений между работниками и работодателями","meh:labor_main_title":"Верховенство закона в трудовых отношениях","meh:labor_main_desc":"Мы оказываем профессиональную помощь в правовом регулировании отношений между работодателями и работниками, разрешении споров и ведении кадровой документации.","meh:srv1_t":"Трудовые Договоры","meh:srv1_d":"Составление, редактирование и проверка законности трудовых договоров.","meh:srv2_t":"Трудовые Споры","meh:srv2_d":"Юридическая помощь в разрешении трудовых споров в судебном и досудебном порядке.","meh:srv3_t":"Кадровая Документация","meh:srv3_d":"Юридически грамотное составление и пересмотр кадровой документации.","meh:srv4_t":"Трудовое Законодательство","meh:srv4_d":"Мониторинг соблюдения требований трудового законодательства и консультирование.","meh:footer_address_text":"г. Ташкент, Юнусабадский район, Центр 4, ул. Абдуллы Кадыри 28А","meh:footer_rights":"Все права защищены.","tax:tax_title":"Налоговое Право","tax:tax_desc":"Обеспечение финансовой стабильности и налоговой безопасности","tax:tax_main_title":"Минимизация налоговых рисков","tax:tax_main_desc":"Наши опытные налоговые консультанты помогут защитить ваш бизнес от излишних налоговых выплат и законно оптимизировать финансовую деятельность.","tax:srv1_t":"Налоговое Планирование","tax:srv1_d":"Разработка эффективных налоговых планов и законное снижение налоговой нагрузки.","tax:srv2_t":"Налоговая Отчетность","tax:srv2_d":"Своевременная и правильная подготовка всех налоговых деклараций и отчетов.","tax:srv3_t":"Взаимодействие с Налоговой","tax:srv3_d":"Представительство в налоговых органах по вопросам проверок и другим вопросам.","tax:srv4_t":"Налоговый Анализ","tax:srv4_d":"Анализ налоговых обязательств компании и предложения по их оптимизации.","ip:ip_title":"Право Интеллектуальной Собственности","ip:ip_desc":"Надежная защита ваших идей и бренда","ip:ip_main_title":"Защита Инноваций и Творчества","ip:ip_main_desc":"Мы предлагаем полный спектр услуг по регистрации, защите и коммерциализации объектов интеллектуальной собственности. Ваши идеи – это ваш капитал.","ip:srv1_t":"Товарные Знаки","ip:srv1_d":"Государственная регистрация товарных знаков и знаков обслуживания для защиты вашего бренда.","ip:srv2_t":"Авторское Право","ip:srv2_d":"Защита и депонирование авторских прав на научные, литературные и художественные произведения.","ip:srv3_t":"Патентование","ip:srv3_d":"Содействие в получении патентов на изобретения, полезные модели и промышленные образцы.","ip:srv4_t":"IP Аудит и Стратегия","ip:srv4_d":"Анализ портфеля интеллектуальной собственности компании и разработка стратегии управления им.","ip:srv5_t":"Лицензирование","ip:srv5_d":"Составление лицензионных договоров и договоров франчайзинга на использование объектов интеллектуальной собственности.","ip:srv6_t":"Разрешение Споров","ip:srv6_d":"Юридическая помощь в борьбе с нарушениями прав интеллектуальной собственности и контрафактной продукцией.","ip:footer_address_text":"г. Ташкент, Юнусабадский район, Центр 4, ул. Абдуллы Кадыри 28А","ip:footer_rights":"Все права защищены.","out:out_title":"Юридическое Сопровождение","out:out_desc":"Профессиональная и постоянная правовая поддержка вашего бизнеса (Аутсорсинг)","out:out_main_title":"Решение лучше штатного юриста","out:out_main_desc":"Юридический аутсорсинг — это передача всех правовых вопросов вашей компании внешней команде профессионалов. Это не только экономнее, но и безопаснее и эффективнее.","out:srv1_t":"Постоянные Консультации","out:srv1_d":"Оперативные консультации 24/7 по любым юридическим вопросам, возникающим в ходе вашей деятельности.","out:srv2_t":"Работа с Договорами","out:srv2_d":"Составление, правовая экспертиза всех видов договоров и предотвращение рисков.","out:srv3_t":"Представительство в Суде","out:srv3_d":"Профессиональная защита интересов компании в экономических, гражданских и административных судах.","out:srv4_t":"Внутренние Документы","out:srv4_d":"Подготовка приказов, положений, инструкций и других внутренних корпоративных документов в соответствии с законом.","out:srv5_t":"Переговоры","out:srv5_d":"Участие во встречах с партнерами и контрагентами и защита ваших интересов.","out:srv6_t":"Правовой Аудит","out:srv6_d":"Анализ существующей документации компании и устранение выявленных недостатков.","out:footer_address_text":"г. Ташкент, Юнусабадский район, Центр 4, ул. Абдуллы Кадыри 28А","out:footer_rights":"Все права защищены.","lic:lic_title":"Лицензии и Разрешения","lic:lic_desc":"Юридическое оформление всех необходимых разрешений для вашего бизнеса","lic:lic_main_title":"Легкое взаимодействие с госорганами","lic:lic_main_desc":"Доверьте сложные бюрократические процессы нам. Мы поможем вам на всех этапах лицензирования и получения разрешений.","lic:srv1_t":"Получение Лицензии","lic:srv1_d":"Полное юридическое сопровождение по получению лицензий. Взаимодействие с госорганами и подготовка документов.","lic:srv2_t":"Разрешения","lic:srv2_d":"Получение разрешений для строительства, импорта-экспорта, здравоохранения и других сфер. Поддержка всех процессов.","lic:srv3_t":"Продление Лицензии","lic:srv3_d":"Обновление и продление сроков существующих лицензий и разрешений. Сервис напоминаний для своевременного продления.","lic:footer_address_text":"г. Ташкент, Юнусабадский район, Центр 4, ул. Абдуллы Кадыри 28А","lic:footer_rights":"Все права защищены.","ex_hero_eyebrow":"Юридический консалтинг — Ташкент","ex_btn_services":"Наши услуги","ex_stat1":"Направлений практики","ex_stat2":"Оперативные консультации","ex_stat3":"Языка обслуживания","ex_stat4":"Онлайн — по всему Узбекистану","ex_btn_faq":"Все вопросы и ответы","ex_label_email":"Email (необязательно)","ex_form_hint":"Заполните поля — наши специалисты свяжутся с вами в ближайшее время.","msg_fill":"Пожалуйста, укажите имя и номер телефона.","ex_cta_t":"Начните решать ваш юридический вопрос уже сегодня","ex_cta_d":"Первичная короткая консультация — бесплатно. Свяжитесь с нами удобным способом.","ex_side_t":"Есть вопрос?","ex_side_d":"Наши специалисты подробно проконсультируют вас по этому направлению.","ex_call":"Позвоните нам","ex_write":"Напишите нам","ex_addr_t":"Адрес","ex_social_t":"Социальные сети","ex_about_pre":"О нас","ex_faq_pre":"Вопросы и ответы","ex_contact_pre":"Контакты","ex_svc_pre":"Услуги","blog:faq16_q":"Обязательно ли обращаться в суд для расторжения брака?","blog:faq16_a":"Нет. При взаимном согласии супругов, отсутствии несовершеннолетних детей и имущественного спора брак расторгается в органе ЗАГС. В остальных случаях дело рассматривается судом.","blog:faq17_q":"Сколько времени даётся на принятие наследства?","blog:faq17_a":"Свидетельство о праве на наследство выдаётся через шесть месяцев со дня открытия наследства; в этот срок нужно обратиться к нотариусу. При пропуске срока по уважительной причине он восстанавливается через суд.","blog:faq18_q":"Что нужно сделать, чтобы стать резидентом IT Park?","blog:faq18_a":"Сначала регистрируется юридическое лицо в Узбекистане, затем через официальный портал IT Park с ЭЦП подаётся заявка. Вид деятельности должен соответствовать разрешённому перечню.","ex_process_pre":"Процесс","ins:ins_title":"Неплатёжеспособность","ins:ins_desc":"Профессиональная правовая помощь по неплатёжеспособности физических и юридических лиц","ins:ins_main_title":"Законный выход из долговой нагрузки","ins:ins_main_desc":"Неплатёжеспособность — это не конец деятельности, а предусмотренная законом возможность начать заново. Мы защищаем интересы должников и кредиторов на всех стадиях судебной процедуры на основании Закона «О неплатёжеспособности» № ЗРУ-763 от 12 апреля 2022 года.","ins:note_t":"Правовая основа","ins:note_d":"Закон Республики Узбекистан «О неплатёжеспособности» № ЗРУ-763 от 12 апреля 2022 года, Экономический процессуальный кодекс и соответствующие постановления Пленума Верховного суда. Каждая ситуация анализируется индивидуально, итоговый результат зависит от обстоятельств дела.","ins:srv1_t":"Неплатёжеспособность юридических лиц","ins:srv1_d":"Возбуждение дела о неплатёжеспособности предприятия, представительство в процедурах наблюдения, судебной санации, внешнего управления и ликвидации.","ins:srv2_t":"Неплатёжеспособность физических лиц","ins:srv2_d":"Подготовка заявления в суд по банковским кредитам и иным долгам граждан, а также разработка плана реструктуризации задолженности.","ins:srv3_t":"Защита интересов кредиторов","ins:srv3_d":"Включение требований в реестр кредиторов, участие в собрании кредиторов и выработка правовой стратегии взыскания долга.","ins:srv4_t":"Санация и мировое соглашение","ins:srv4_d":"Подготовка плана финансового оздоровления предприятия, согласование мирового соглашения с кредиторами и его утверждение судом.","ins:srv5_t":"Оспаривание сделок и ответственность","ins:srv5_d":"Признание подозрительных сделок должника недействительными, дела о субсидиарной ответственности руководителей и учредителей.","ins:srv6_t":"Индивидуальные предприниматели","ins:srv6_d":"Полное юридическое сопровождение должников со статусом ИП с учётом особенностей процедуры.","ins:steps_t":"Как ведётся дело","ins:steps_d":"Четыре этапа — понятно и прозрачно","ins:step1_t":"Финансовый анализ","ins:step1_d":"Оцениваются структура долга, активы и признаки неплатёжеспособности.","ins:step2_t":"Подготовка документов","ins:step2_d":"Формируются заявление в суд, приложения и доказательственная база.","ins:step3_t":"Представительство в суде","ins:step3_d":"Ваши интересы защищаются на всех стадиях процедуры.","ins:step4_t":"Итоговый результат","ins:step4_d":"Долги реструктурируются или списываются, процедура завершается.","ins:faq_t":"Часто задаваемые вопросы","ins:faq_d":"Наиболее частые вопросы по направлению неплатёжеспособности","ins:faq1_q":"Когда физическое лицо может быть признано неплатёжеспособным?","ins:faq1_a":"Обратиться в суд можно, если должник не исполнил денежные обязательства в течение трёх месяцев и сумма долга составляет не менее 200-кратного размера базовой расчётной величины. Каждый случай оценивается индивидуально на основании документов.","ins:faq2_q":"Каковы признаки неплатёжеспособности юридического лица?","ins:faq2_a":"Закон предусматривает два признака: временная неплатёжеспособность — неисполнение обязательства в течение трёх месяцев (для градообразующих и приравненных к ним предприятий — шести месяцев); постоянная неплатёжеспособность — превышение обязательств должника над стоимостью его активов.","ins:faq3_q":"Какие процедуры применяются?","ins:faq3_a":"К юридическому лицу могут применяться наблюдение, судебная санация, внешнее управление, ликвидационная процедура и мировое соглашение. К физическому лицу — план реструктуризации долга, процедура реализации имущества и мировое соглашение.","ins:faq4_q":"В каком суде рассматривается дело?","ins:faq4_a":"Дело в отношении юридического лица рассматривается судом по месту его государственной регистрации, а в отношении физического лица и индивидуального предпринимателя — судом по месту жительства, по правилам Экономического процессуального кодекса.","ins:faq5_q":"Изымается ли всё имущество в ходе процедуры?","ins:faq5_a":"Нет. Законодательством установлен перечень имущества, на которое не может быть обращено взыскание, и он учитывается в рамках процедуры. В отношении заложенного имущества действуют отдельные правила — ситуация анализируется по каждому делу индивидуально.","ins:faq6_q":"Есть ли ответственность за фиктивную неплатёжеспособность?","ins:faq6_a":"Да. За преднамеренную или фиктивную неплатёжеспособность предусмотрена административная и уголовная ответственность. Кроме того, к руководителю и учредителям предприятия может быть применена субсидиарная ответственность.","fam:fam_title":"Семейное Право","fam:fam_desc":"Надёжная правовая помощь по вопросам брака, развода, алиментов, детей, имущества и наследства","fam:fam_main_title":"Спокойное и справедливое решение семейных вопросов","fam:fam_main_desc":"Семейные споры всегда личные и деликатные. Опираясь на нормы Семейного и Гражданского кодексов Республики Узбекистан, мы защищаем интересы клиента и прежде всего детей, стремясь по возможности достичь досудебного соглашения.","fam:note_t":"Правовая основа","fam:note_d":"Семейный кодекс, Гражданский кодекс (раздел V — «Наследственное право») и Гражданский процессуальный кодекс Республики Узбекистан, а также постановления Пленума Верховного суда о расторжении брака и наследственном праве. Консультация даётся исходя из конкретных обстоятельств семьи.","fam:srv1_t":"Расторжение брака","fam:srv1_d":"Расторжение брака через органы ЗАГС или в судебном порядке, подготовка искового заявления и представительство в судебных заседаниях.","fam:srv2_t":"Раздел имущества","fam:srv2_d":"Раздел совместного имущества супругов, выделение личной собственности и оформление соглашения о разделе.","fam:srv3_t":"Алиментные вопросы","fam:srv3_d":"Взыскание алиментов в долях или в твёрдой сумме, изменение размера и взыскание задолженности.","fam:srv4_t":"Споры о детях","fam:srv4_d":"Определение места жительства ребёнка, порядок общения со вторым родителем, установление отцовства и усыновление.","fam:srv5_t":"Наследство и наследование","fam:srv5_d":"Оформление принятия наследства, восстановление срока, обязательная доля и споры между наследниками.","fam:srv6_t":"Завещание и брачный договор","fam:srv6_d":"Составление завещания и брачного договора, нотариальное удостоверение, а также признание их недействительными в суде.","fam:steps_t":"Как мы работаем","fam:steps_d":"Деликатный и поэтапный подход к чувствительным вопросам","fam:step1_t":"Конфиденциальная беседа","fam:step1_d":"Выслушиваем ситуацию, изучаем документы и объясняем реальные перспективы.","fam:step2_t":"Досудебное соглашение","fam:step2_d":"При наличии возможности стремимся достичь соглашения между сторонами.","fam:step3_t":"Защита в суде","fam:step3_d":"При отсутствии соглашения готовится иск и ваши интересы защищаются в суде.","fam:step4_t":"Оформление","fam:step4_d":"Решение оформляется в ЗАГС или у нотариуса, контролируется его исполнение.","fam:faq_t":"Часто задаваемые вопросы","fam:faq_d":"Наиболее частые вопросы по семейному праву","fam:faq1_q":"В каких случаях брак расторгается через ЗАГС?","fam:faq1_a":"Если супруги согласны, у них нет общих несовершеннолетних детей и отсутствует спор об имуществе или содержании, брак расторгается в органе ЗАГС. В остальных случаях дело рассматривается в судебном порядке.","fam:faq2_q":"Как определяется размер алиментов?","fam:faq2_a":"При отсутствии соглашения между родителями суд взыскивает 1/4 ежемесячного заработка и иного дохода на одного ребёнка, 1/3 — на двоих, 1/2 — на троих и более. Размер на каждого ребёнка не может быть менее 26,5 процента установленного законом минимального размера оплаты труда.","fam:faq3_q":"Как делится совместное имущество супругов?","fam:faq3_a":"Имущество, нажитое в браке, считается общим и, как правило, делится в равных долях. Суд может отступить от равенства долей с учётом интересов несовершеннолетних детей или иных заслуживающих внимания обстоятельств. Имущество, принадлежавшее до брака либо полученное в наследство или в дар, является личной собственностью.","fam:faq4_q":"Каков срок принятия наследства?","fam:faq4_a":"Свидетельство о праве на наследство выдаётся по истечении шести месяцев со дня открытия наследства; в этот срок необходимо обратиться к нотариусу. При пропуске срока по уважительной причине он может быть восстановлен в судебном порядке.","fam:faq5_q":"Можно ли получить обязательную долю при наличии завещания?","fam:faq5_a":"Да. Несовершеннолетние или нетрудоспособные дети завещателя, его нетрудоспособный супруг и родители имеют право на обязательную долю в наследстве независимо от содержания завещания.","fam:faq6_q":"К каким последствиям приводит неуплата алиментов?","fam:faq6_a":"Задолженность взыскивается в порядке принудительного исполнения, исполнитель может наложить ограничения на имущество и счета, а также временно запретить выезд за границу. Длительная неуплата может повлечь административную и уголовную ответственность.","itp:itp_title":"Резидентство IT Park","itp:itp_desc":"Статус резидента, налоговые льготы и правовое оформление экспортной деятельности для IT-компаний","itp:itp_main_title":"Льготное правовое поле для вашего IT-бизнеса","itp:itp_main_desc":"Резидентство IT Park даёт технологическим компаниям в Узбекистане значительные налоговые и таможенные льготы. Мы сопровождаем на всех этапах — от правильного выбора вида деятельности до подачи заявки, заключения договора и выполнения отчётных обязательств.","itp:note_t":"Важное примечание","itp:note_d":"Льготы определяются действующим Налоговым кодексом, указами Президента и постановлениями правительства, регулирующими деятельность IT Park, и периодически обновляются. Конкретные ставки, сроки и перечень разрешённых видов деятельности проверяются по редакции, действующей на дату обращения.","itp:srv1_t":"Получение статуса резидента","itp:srv1_d":"Подготовка бизнес-плана, оформление заявки и заключение договора об условиях деятельности резидента с дирекцией IT Park.","itp:srv2_t":"Создание компании и вид деятельности","itp:srv2_d":"Регистрация в форме ООО или иной форме и корректный выбор кода в соответствии с перечнем разрешённых видов деятельности.","itp:srv3_t":"Налоговые льготы и отчётность","itp:srv3_d":"Законное применение льгот, порядок подачи ежеквартальной отчётности и предварительная оценка налоговых рисков.","itp:srv4_t":"Экспорт и валютные операции","itp:srv4_d":"Договоры с иностранными заказчиками, оформление экспорта IT-услуг и консультации по валютной выручке.","itp:srv5_t":"IT Visa и иностранные специалисты","itp:srv5_d":"Оформление визы, регистрации и трудовых отношений для иностранных учредителей и специалистов.","itp:srv6_t":"Защита программных продуктов","itp:srv6_d":"Правовое закрепление IT-продукта через авторское право, товарный знак, NDA, лицензионные и аутсорсинговые договоры.","itp:steps_t":"Путь к резидентству","itp:steps_d":"Четыре этапа — от подготовки до постоянного сопровождения","itp:step1_t":"Оценка деятельности","itp:step1_d":"Проверяется соответствие вашей бизнес-модели разрешённым видам деятельности.","itp:step2_t":"Оформление компании","itp:step2_d":"Создаётся юридическое лицо либо существующие документы приводятся в соответствие.","itp:step3_t":"Заявка и договор","itp:step3_d":"Заявка подаётся через портал и подписывается договор резидента.","itp:step4_t":"Постоянное сопровождение","itp:step4_d":"Оказывается помощь по отчётности, договорам и сохранению льгот.","itp:faq_t":"Часто задаваемые вопросы","itp:faq_d":"Наиболее частые вопросы о резидентстве IT Park","itp:faq1_q":"Какими налоговыми льготами пользуются резиденты?","itp:faq1_a":"Для резидентов установлена нулевая ставка по налогу на прибыль, налогу с оборота и социальному налогу, а подоходный налог сотрудников составляет 7,5 процента. Также действуют таможенные льготы по отдельному оборудованию, ввозимому для собственных нужд. Конкретные ставки и сроки действия проверяются по актуальной редакции.","itp:faq2_q":"Куда и как подаётся заявка?","itp:faq2_a":"После регистрации компании как юридического лица в Узбекистане заявка подаётся онлайн через официальный портал IT Park с использованием электронной цифровой подписи. К заявке прилагаются бизнес-план и учредительные документы.","itp:faq3_q":"Может ли любая IT-компания стать резидентом?","itp:faq3_a":"Нет. Статус предоставляется только компаниям, чья деятельность входит в установленный законодательством перечень разрешённых видов. Не всякий бизнес, связанный с компьютерами или технологиями, автоматически попадает в этот перечень, поэтому вид деятельности следует проверять заранее.","itp:faq4_q":"Обязательно ли компании находиться в Ташкенте?","itp:faq4_a":"Нет. Статус резидента и связанные с ним льготы действуют для компаний, зарегистрированных в любом регионе Узбекистана, — физическое присутствие в Ташкенте не требуется.","itp:faq5_q":"Какие обязанности есть у резидента?","itp:faq5_a":"Резидент обязан соблюдать обязательства по договору об условиях деятельности с IT Park и ежеквартально представлять сведения о своей деятельности. При неисполнении обязательств статус и льготы могут быть прекращены.","itp:faq6_q":"Какие возможности есть для иностранных учредителей и специалистов?","itp:faq6_a":"Для иностранных специалистов предусмотрен специальный визовый режим, возможность выплаты дивидендов и заработной платы в иностранной валюте, а также программы поддержки иностранных компаний. Условия каждой программы проверяются отдельно.","ex_map_open":"Открыть на карте","ex_map_route":"Построить маршрут","ex_note_t":"Правовая основа","ex_steps_t":"Порядок работы","ex_steps_d":"Четыре этапа — понятное и прозрачное сотрудничество","ex_faq_t":"Часто задаваемые вопросы","ex_faq_d":"Наиболее частые вопросы по этому направлению","ex_geo_t":"Наш офис","ex_geo_d":"Мы находимся в Юнусабадском районе города Ташкента","korp:note_d":"Гражданский кодекс Республики Узбекистан, законы «Об обществах с ограниченной и дополнительной ответственностью» и «Об акционерных обществах и защите прав акционеров», а также Закон «О гарантиях свободы предпринимательской деятельности».","korp:step1_t":"Анализ бизнес-модели","korp:step1_d":"Оцениваются вид деятельности, организационно-правовая форма и состав учредителей.","korp:step2_t":"Подготовка учредительных документов","korp:step2_d":"Устав, учредительный договор и решения участников составляются в соответствии с законодательством.","korp:step3_t":"Государственная регистрация","korp:step3_d":"Документы подаются через портал государственных услуг и оформляется свидетельство.","korp:step4_t":"Запуск деятельности","korp:step4_d":"Оформляются банковский счёт, ЭЦП, внутренние документы и постановка на налоговый учёт.","korp:pfaq1_q":"Сколько времени занимает открытие ООО?","korp:pfaq1_a":"При полном и корректном пакете документов государственная регистрация в электронном виде занимает от 30 минут до одного рабочего дня. Основное время уходит на предварительную подготовку документов.","korp:pfaq2_q":"Установлен ли минимальный уставный капитал?","korp:pfaq2_a":"Для общества с ограниченной ответственностью минимальный размер законодательством не установлен — учредители определяют его самостоятельно. Для отдельных лицензируемых видов деятельности и финансового сектора действуют особые требования.","korp:pfaq3_q":"Может ли иностранное лицо учредить компанию?","korp:pfaq3_a":"Да. Иностранные физические и юридические лица могут быть учредителями компании в Узбекистане. К предприятиям с иностранными инвестициями могут применяться дополнительные требования к уставному фонду и оформлению документов.","korp:pfaq4_q":"Что нужно для смены директора?","korp:pfaq4_a":"Принимается решение общего собрания участников (акционеров), оформляется трудовой договор с новым руководителем и изменение вносится в государственный реестр. Также обновляются банковские данные и ЭЦП.","korp:pfaq5_q":"Сколько длится ликвидация компании?","korp:pfaq5_a":"Добровольная ликвидация включает уведомление кредиторов, завершение расчётов и налоговую проверку. На практике процесс занимает несколько месяцев и зависит от объёма обязательств предприятия.","meh:note_d":"Действующий Трудовой кодекс Республики Узбекистан, постановления Пленума Верховного суда по трудовым спорам, а также постановления правительства об оплате труда и рабочем времени.","meh:step1_t":"Аудит кадровых документов","meh:step1_d":"Проверяется соответствие трудовых договоров, приказов и внутренних документов законодательству.","meh:step2_t":"Устранение недостатков","meh:step2_d":"Выявленные ошибки исправляются, недостающие документы разрабатываются.","meh:step3_t":"Досудебное урегулирование","meh:step3_d":"Спор пытаются урегулировать через комиссию по трудовым спорам или переговоры.","meh:step4_t":"Представительство в суде","meh:step4_d":"При отсутствии соглашения готовится иск и ваши интересы защищаются в суде.","meh:pfaq1_q":"Какова максимальная продолжительность испытательного срока?","meh:pfaq1_a":"По общему правилу испытательный срок не превышает трёх месяцев; для отдельных категорий работников может быть установлен более длительный срок. Условие об испытании должно быть прямо указано в трудовом договоре, иначе работник считается принятым без испытания.","meh:pfaq2_q":"За сколько дней работник предупреждает об увольнении?","meh:pfaq2_a":"При увольнении по собственному желанию работник обязан письменно предупредить работодателя не менее чем за две недели — 14 календарных дней. По соглашению сторон договор может быть расторгнут и в более короткий срок.","meh:pfaq3_q":"Куда обращаться при незаконном увольнении?","meh:pfaq3_a":"Можно обратиться в комиссию по трудовым спорам либо непосредственно в суд. Для требований о восстановлении на работе установлен сокращённый срок обращения, поэтому важно не откладывать обращение к юристу.","meh:pfaq4_q":"Обязательны ли правила внутреннего трудового распорядка?","meh:pfaq4_a":"Да. Правила внутреннего трудового распорядка, штатное расписание и должностные инструкции должны быть в каждой организации. Их отсутствие при проверках может повлечь административную ответственность.","meh:pfaq5_q":"Как оформляется дистанционная работа?","meh:pfaq5_a":"Условия дистанционной работы и неполного рабочего времени закрепляются письменно в трудовом договоре или дополнительном соглашении к нему. Порядок учёта рабочего времени и оплаты труда также должен быть чётко определён.","tax:note_d":"Налоговый кодекс Республики Узбекистан, указы Президента и постановления правительства о налоговых льготах, а также официальные разъяснения налоговых органов.","tax:step1_t":"Анализ налогового положения","tax:step1_d":"Оцениваются действующий налоговый режим, отчётность и имеющиеся риски.","tax:step2_t":"План оптимизации","tax:step2_d":"Предлагаются варианты использования законных льгот и режимов.","tax:step3_t":"Оформление отчётности","tax:step3_d":"Декларации и отчёты корректно составляются и подаются в срок.","tax:step4_t":"Защита при проверках","tax:step4_d":"Взаимодействие с налоговыми органами и при необходимости защита в порядке обжалования и в суде.","tax:pfaq1_q":"Какова ставка налога с оборота?","tax:pfaq1_a":"Общая ставка составляет 4 процента. Для отдельных регионов, видов деятельности и категорий предпринимателей предусмотрены пониженные ставки — конкретная ставка зависит от вашего вида деятельности.","tax:pfaq2_q":"Когда обязательна регистрация плательщиком НДС?","tax:pfaq2_a":"При превышении годового оборота установленного законом порога — одного миллиарда сумов — предприятие переходит на уплату налога на добавленную стоимость и налога на прибыль. Стать плательщиком НДС можно и добровольно.","tax:pfaq3_q":"Уведомляют ли заранее о налоговой проверке?","tax:pfaq3_a":"Плановые проверки проводятся в установленном порядке с предварительным уведомлением. Для оперативных и встречных проверок предусмотрены отдельные основания и порядок.","tax:pfaq4_q":"Можно ли обжаловать решение налогового органа?","tax:pfaq4_a":"Да. Решение можно обжаловать в вышестоящий налоговый орган либо непосредственно в суд. Требуется строгое соблюдение сроков подачи жалобы, иначе право утрачивается.","tax:pfaq5_q":"Какие меры применяются при налоговой задолженности?","tax:pfaq5_a":"При несвоевременной уплате могут применяться предусмотренные законом меры принудительного взыскания — в том числе приостановление операций по счетам и обращение взыскания на имущество. Своевременное обращение позволяет предотвратить такие последствия.","ip:note_d":"Законы «О товарных знаках, знаках обслуживания и наименованиях мест происхождения товаров», «Об авторском праве и смежных правах», «Об изобретениях, полезных моделях и промышленных образцах», а также соответствующие нормы Гражданского кодекса.","ip:step1_t":"Предварительный поиск","ip:step1_d":"Проверяется, не пересекается ли обозначение или решение с уже зарегистрированными.","ip:step2_t":"Подготовка заявки","ip:step2_d":"Корректно подбираются описание, изображение и классы товаров и услуг.","ip:step3_t":"Прохождение экспертизы","ip:step3_d":"Даются ответы на запросы уполномоченного органа и снимаются возражения.","ip:step4_t":"Свидетельство и защита","ip:step4_d":"Получается свидетельство, отслеживается срок действия и принимаются меры против нарушений.","ip:pfaq1_q":"Сколько занимает регистрация товарного знака?","ip:pfaq1_a":"В стандартном порядке процесс занимает несколько месяцев и зависит от этапов экспертизы. Возможно использование ускоренной экспертизы, которая существенно сокращает срок.","ip:pfaq2_q":"Обязателен ли поиск перед регистрацией?","ip:pfaq2_a":"Формально не обязателен, однако предварительный поиск выявляет сходные обозначения и существенно снижает риск отказа и последующих споров. Мы всегда его рекомендуем.","ip:pfaq3_q":"Регистрируется ли авторское право?","ip:pfaq3_a":"Авторское право возникает с момента создания произведения и не требует регистрации. Добровольное депонирование служит доказательством авторства при возникновении спора.","ip:pfaq4_q":"На какой срок выдаётся товарный знак?","ip:pfaq4_a":"Право на товарный знак предоставляется на десять лет и может продлеваться на тот же срок неограниченное число раз. Для продления необходимо обратиться до истечения срока.","ip:pfaq5_q":"Что делать, если знак использует кто-то другой?","ip:pfaq5_a":"Сначала нарушение фиксируется документально и нарушителю направляется претензия. При отсутствии результата подаётся иск в суд с требованием запретить использование, изъять контрафакт и взыскать убытки.","out:note_d":"Услуга оформляется договором на основании норм Гражданского кодекса о возмездном оказании услуг. Представительство в судах осуществляется в соответствии с Гражданским процессуальным, Экономическим процессуальным и Административным процессуальным кодексами.","out:step1_t":"Правовой аудит","out:step1_d":"Единовременно полностью изучаются действующие договоры, внутренние документы и риски.","out:step2_t":"Договор и тариф","out:step2_d":"Подбирается месячный тариф по объёму работы и подписывается договор на обслуживание.","out:step3_t":"Ежедневное сопровождение","out:step3_d":"Оказывается оперативная правовая помощь по договорам, приказам и обращениям.","out:step4_t":"Отчётность и развитие","out:step4_d":"Предоставляется отчёт о выполненной работе и предлагаются меры по снижению рисков.","out:pfaq1_q":"Чем аутсорсинг отличается от штатного юриста?","out:pfaq1_a":"Вместо одного юриста работает команда специалистов по разным направлениям: корпоративному, трудовому, налоговому праву и судебной практике. При этом отсутствуют расходы на зарплату, налоги и отпуска.","out:pfaq2_q":"На какой срок заключается договор?","out:pfaq2_a":"Обычно заключается на один год с ежемесячной оплатой. Для пробного периода может быть согласован и более короткий срок; порядок расторжения заранее определяется в документе.","out:pfaq3_q":"Кто представляет интересы в суде?","out:pfaq3_a":"По гражданским, экономическим и административным делам наши юристы представляют интересы на основании доверенности. Защита по уголовным делам согласно закону осуществляется только лицом со статусом адвоката.","out:pfaq4_q":"Как обеспечивается конфиденциальность?","out:pfaq4_a":"В договор включается условие о конфиденциальности, при необходимости подписывается отдельное NDA. Документы передаются ограниченному кругу ответственных сотрудников и не раскрываются третьим лицам.","out:pfaq5_q":"Меняется ли оплата при росте объёма работы?","out:pfaq5_a":"Месячный тариф покрывает согласованный объём работы. Дополнительные работы, такие как судебные процессы или крупные сделки, согласовываются заранее отдельно — неожиданных платежей не возникает.","lic:note_d":"Закон № ЗРУ-701 от 14 июля 2021 года «О лицензировании, разрешительных и уведомительных процедурах», Указ Президента № УП-6044 от 24 августа 2020 года и соответствующие единые положения Кабинета Министров.","lic:step1_t":"Определение процедуры","lic:step1_d":"Определяется, требует ли ваша деятельность лицензии, разрешения или уведомления.","lic:step2_t":"Приведение в соответствие","lic:step2_d":"Персонал, помещение, техника и документы приводятся в соответствие с лицензионными требованиями.","lic:step3_t":"Подача заявки онлайн","lic:step3_d":"Заявка направляется через информационную систему «Лицензия» или портал государственных услуг.","lic:step4_t":"Контроль и продление","lic:step4_d":"Отслеживаются сроки, переоформление и продление осуществляются своевременно.","lic:pfaq1_q":"В чём разница между лицензией, разрешением и уведомлением?","lic:pfaq1_a":"Это три разные процедуры. Лицензия предполагает наиболее строгие требования, разрешение выдаётся в более простом порядке, а при уведомлении для начала деятельности достаточно уведомить уполномоченный орган.","lic:pfaq2_q":"Куда подаётся заявка?","lic:pfaq2_a":"Заявка подаётся онлайн через информационную систему «Лицензия» или Единый портал интерактивных государственных услуг с использованием электронной цифровой подписи.","lic:pfaq3_q":"Каковы основания для отказа в выдаче лицензии?","lic:pfaq3_a":"Законом предусмотрены три основных основания: представление документов не в полном объёме; несоответствие заявителя лицензионным требованиям и условиям; наличие в представленных документах недостоверных или искажённых сведений.","lic:pfaq4_q":"Можно ли обжаловать отказ?","lic:pfaq4_a":"Да. Заявитель вправе в установленном порядке обжаловать решение лицензирующего органа и действия (бездействие) его должностных лиц непосредственно в суд.","lic:pfaq5_q":"Что происходит по истечении срока?","lic:pfaq5_a":"Продолжение деятельности по лицензии с истёкшим сроком является нарушением закона и влечёт ответственность. Поэтому за продлением следует обращаться до истечения срока."},"en":{"nav_home":"Home","nav_services":"Services","nav_about":"About Us","nav_blog":"Blog","nav_contact":"Contact","nav_contact_btn":"Get in Touch","service1_title":"Corporate Law","service2_title":"Labor Law","service3_title":"Tax Law","service_ip_title":"Intellectual Property","service_out_title":"Legal Outsourcing","service6_title":"Licenses and Permits","service1_desc":"Company formation, registration, corporate governance, shareholder agreements, restructuring, liquidation.","service2_desc":"Employment contracts, disputes, dismissals, internal documents, employee rights protection.","service3_desc":"Tax planning, reporting, working with tax authorities, utilizing tax benefits.","service_ip_desc":"Brand and copyright protection.","service_out_desc":"Ongoing legal support for business.","service6_desc":"Obtaining licenses for activities, permits, certificates, state registration.","service_ins_title":"Insolvency","service_ins_desc":"Declaring individuals and legal entities insolvent, debt restructuring, rehabilitation, liquidation procedures and work with creditors.","service_fam_title":"Family law","service_fam_desc":"Divorce, division of marital property, alimony, child-related disputes, inheritance, wills and prenuptial agreements.","service_itp_title":"IT Park residency","service_itp_desc":"Obtaining IT Park resident status, applying tax incentives, export contracts, IT Visa and legal protection of software products.","home:hero_title":"Professional Legal Services","home:hero_desc":"Our experienced lawyers will help protect your rights and grow your business.","home:hero_btn":"Get Consultation","home:services_title":"Our Services","home:services_desc":"We offer all the legal services your company needs","more_btn":"Learn More","home:contact_title":"Contact","home:contact_desc":"Contact us for legal advice","home:contact_info":"Contact Information","contact_address":"Tashkent, Yunusabad district, Center 4, Abdulla Qodiriy street 28A","home:social_media":"Social Media","home:name_placeholder":"Your Name","home:email_placeholder":"Your Email","home:phone_placeholder":"Your Phone","home:message_placeholder":"Your Message","home:send_btn":"Send Message","msg_success":"Message sent!","msg_error":"Error occurred.","footer_desc":"Our law firm provides quality services to meet all the legal needs of our clients.","services_footer":"Services","home:service1_footer":"Corporate Law","home:service2_footer":"Labor Law","home:service3_footer":"Tax Law","home:service6_footer":"Licenses and Permits","links_footer":"Useful Links","blog_footer":"Blog","about_footer":"About Us","contact_footer":"Contact","rights_text":"All rights reserved.","about:about_title":"About Us","about:about_desc":"VeroLex Advisory - your reliable legal partner for entrepreneurs","about:about_subtitle":"Special Approach for Business Owners","about:about_text1":"VeroLex Advisory has been providing high-quality legal services to entrepreneurs in Uzbekistan since 2020. Our main goal is to ensure the legal security of your business.","about:about_text2":"Our lawyers are experts who deeply understand business processes. We solve legal problems and offer strategic advice to help your business grow.","about:why_us_title":"Why Choose Us?","about:why_us_subtitle":"Special solutions and benefits for business owners","about:feat1_title":"Special Approach","about:feat1_desc":"Our lawyers deeply understand the problems of business owners and offer appropriate solutions.","about:feat2_title":"Business Growth","about:feat2_desc":"We not only solve legal issues but also offer strategies to help your business grow and develop.","about:feat3_title":"Fast and Efficient","about:feat3_desc":"Since business processes are fast-paced, we focus on providing fast and efficient legal services.","about:feat4_title":"Risk Protection","about:feat4_desc":"Professional advice on protecting your business from legal risks and preventing future problems.","about:feat5_title":"Long-term Partnership","about:feat5_desc":"We provide legal support at all stages of your business and value long-term reliable partnership.","about:feat6_title":"Affordable Prices","about:feat6_desc":"We offer special tariffs and payment plans suitable for your financial capabilities.","blog:blog_title":"Blog & FAQ","blog:blog_desc":"Answers to the most important legal questions","blog:faq_title":"Questions & Answers","blog:faq_subtitle":"Answers to the 18 most frequently asked questions by our clients","blog:faq1_q":"What is needed to open an LLC and how long does it take?","blog:faq1_a":"Copies of founders' passports, company name, and charter capital amount are needed. Online registration takes from 30 mins to 24 hours.","blog:faq2_q":"What is the minimum charter capital?","blog:faq2_a":"There is no minimum amount set by law for LLCs. Founders can determine any amount (e.g., 1 million UZS).","blog:faq3_q":"What is the procedure for hiring with a probation period?","blog:faq3_a":"According to the new Labor Code, probation cannot exceed 3 months (6 months for executives). It must be stated in the contract.","blog:faq4_q":"How much notice is needed for resignation?","blog:faq4_a":"An employee must give written notice to the employer at least 14 calendar days before resigning.","blog:faq5_q":"What is the current turnover tax rate?","blog:faq5_a":"The general rate is 4%. However, reduced rates up to 1% exist for businesses in remote areas or special categories.","blog:faq6_q":"When does VAT registration become mandatory?","blog:faq6_a":"If a company's annual turnover exceeds 1 billion UZS, it automatically becomes a payer of VAT and profit tax.","blog:faq7_q":"How long does trademark registration take?","blog:faq7_a":"Standard process takes 7-8 months. Accelerated procedure takes 1-2 months.","blog:faq8_q":"How to protect copyright?","blog:faq8_a":"Copyright arises upon creation. However, depositing the work in the National Depository is recommended to prevent disputes.","blog:faq9_q":"What is legal outsourcing?","blog:faq9_a":"It means hiring an external firm instead of a full-time lawyer for a monthly fee. It is cheaper and more efficient.","blog:faq10_q":"How are service prices determined?","blog:faq10_a":"Prices depend on volume and complexity. We offer hourly rates, one-time services, or monthly subscriptions.","blog:faq11_q":"What is required for a construction license?","blog:faq11_a":"Special equipment, qualified engineers, an office, and ISO certificates are required. Based on 'Transparent Construction' rating.","blog:faq12_q":"Is a license needed for a study center?","blog:faq12_a":"Yes, non-state educational services must be licensed by the Education Inspectorate.","blog:faq13_q":"Can an individual legally write off debts?","blog:faq13_a":"Yes. Under the Law on Insolvency, a court application is possible where obligations have gone unmet for three months and the debt is at least 200 times the base calculation value.","blog:faq14_q":"Is the initial consultation free?","blog:faq14_a":"Yes, brief answers to general questions via phone/Telegram are free. Document review and deep analysis are paid.","blog:faq15_q":"Can services be provided remotely?","blog:faq15_a":"Absolutely. We serve all of Uzbekistan online (Zoom, Telegram, E-mail). Documents are signed via digital signature.","contact:contact_hero_title":"Contact Us","contact:contact_hero_desc":"Do you have questions? Get in touch with us!","contact:contact_info_title":"Contact Information","contact:label_address":"Address:","contact:text_address":"Tashkent, Yunusabad district, Center 4, Abdulla Qodiriy street 28A","contact:label_phone":"Phone:","contact:label_email":"Email:","contact:social_title":"Social Media","contact:form_title":"Send Message","contact:label_name":"Your Name","contact:ph_name":"Enter your name","contact:label_phone_input":"Phone Number","contact:ph_phone":"+998","contact:label_message":"Message","contact:ph_message":"Write your message...","contact:btn_send":"Send","contact:footer_services_title":"Services","contact:footer_links_title":"Useful Links","contact:footer_contact_title":"Contact","contact:footer_address_text":"Tashkent, Yunusabad district, Center 4, Abdulla Qodiriy street 28A","contact:footer_rights":"All rights reserved.","korp:corp_title":"Corporate Law","korp:corp_desc":"Legal solutions for company formation and efficient business management","korp:corp_main_title":"A Solid Foundation for Your Business","korp:corp_main_desc":"Corporate law is the foundation of any business. We provide professional assistance at all stages, from company registration to resolving complex corporate disputes.","korp:srv1_t":"Company Formation","korp:srv1_d":"Establishment of new companies, opening branches, preparation of all legal documents, and registration with state authorities.","korp:srv2_t":"Corporate Governance","korp:srv2_d":"Shareholder agreements, board of directors decisions, shareholder meetings, and management body activities.","korp:srv3_t":"Contracts Drafting","korp:srv3_d":"Drafting, editing, and legal advice on various contracts (sales, services, partnership, etc.).","korp:srv4_t":"Reorganization","korp:srv4_d":"Legal services for company mergers, divisions, reorganization, and liquidation.","korp:srv5_t":"Legal Expertise","korp:srv5_d":"Legal review of existing contracts, identification of deficiencies, and advice on their elimination.","korp:srv6_t":"Dispute Resolution","korp:srv6_d":"Legal assistance in resolving disputes between shareholders, directors, and management bodies.","other_services":"Other Services","korp:footer_address_text":"Tashkent, Yunusabad district, Center 4, Abdulla Qodiriy street 28A","korp:footer_rights":"All rights reserved.","meh:labor_title":"Labor Law","meh:labor_desc":"Regulating relations between employees and employers","meh:labor_main_title":"Rule of Law in Labor Relations","meh:labor_main_desc":"We provide professional assistance in legal regulation of relations between employers and employees, dispute resolution, and HR documentation management.","meh:srv1_t":"Employment Contracts","meh:srv1_d":"Drafting, editing, and verifying the legality of employment contracts.","meh:srv2_t":"Labor Disputes","meh:srv2_d":"Legal assistance in resolving labor disputes in court and pre-trial proceedings.","meh:srv3_t":"HR Documentation","meh:srv3_d":"Legally correct drafting and review of HR documentation.","meh:srv4_t":"Labor Legislation","meh:srv4_d":"Monitoring compliance with labor legislation requirements and providing advice.","meh:footer_address_text":"Tashkent, Yunusabad district, Center 4, Abdulla Qodiriy street 28A","meh:footer_rights":"All rights reserved.","tax:tax_title":"Tax Law","tax:tax_desc":"Ensuring financial stability and tax security","tax:tax_main_title":"Minimizing Tax Risks","tax:tax_main_desc":"Our experienced tax consultants protect your business from excessive tax payments and help legally optimize your financial activities.","tax:srv1_t":"Tax Planning","tax:srv1_d":"Developing effective tax plans and legally reducing the tax burden for your company.","tax:srv2_t":"Tax Reporting","tax:srv2_d":"Timely and correct preparation of all tax declarations and reports.","tax:srv3_t":"Communication with Authorities","tax:srv3_d":"Representation with tax authorities regarding audits and other issues.","tax:srv4_t":"Tax Analysis","tax:srv4_d":"Analysis of your company's tax obligations and proposals for their optimization.","ip:ip_title":"Intellectual Property Law","ip:ip_desc":"Reliable protection of your ideas and brand","ip:ip_main_title":"Protecting Innovation and Creativity","ip:ip_main_desc":"We offer a full range of services for the registration, protection, and commercialization of intellectual property objects. Your ideas are your capital.","ip:srv1_t":"Trademarks","ip:srv1_d":"State registration of trademarks and service marks to protect your brand.","ip:srv2_t":"Copyright","ip:srv2_d":"Protection and depositing of copyright for scientific, literary, and artistic works.","ip:srv3_t":"Patenting","ip:srv3_d":"Assistance in obtaining patents for inventions, utility models, and industrial designs.","ip:srv4_t":"IP Audit & Strategy","ip:srv4_d":"Analysis of your company's intellectual property portfolio and development of a management strategy.","ip:srv5_t":"Licensing & Franchising","ip:srv5_d":"Drafting licensing and franchising agreements for the use of intellectual property objects.","ip:srv6_t":"Dispute Resolution","ip:srv6_d":"Legal assistance in combating intellectual property infringements and counterfeit products.","ip:footer_address_text":"Tashkent, Yunusabad district, Center 4, Abdulla Qodiriy street 28A","ip:footer_rights":"All rights reserved.","out:out_title":"Legal Outsourcing","out:out_desc":"Professional and ongoing legal support for your business","out:out_main_title":"Better Solution than In-house Lawyer","out:out_main_desc":"Legal outsourcing means entrusting all your company's legal issues to an external professional team. It is not only cost-effective but also safer and more efficient.","out:srv1_t":"Ongoing Consultation","out:srv1_d":"Prompt 24/7 advice on any legal questions arising during your business activities.","out:srv2_t":"Contract Management","out:srv2_d":"Drafting, legal expertise of all types of contracts, and risk prevention.","out:srv3_t":"Court Representation","out:srv3_d":"Professional protection of company interests in economic, civil, and administrative courts.","out:srv4_t":"Internal Documentation","out:srv4_d":"Preparation of orders, regulations, instructions, and other internal corporate documents in accordance with the law.","out:srv5_t":"Negotiations","out:srv5_d":"Participation in meetings with partners and counterparties and protection of your interests.","out:srv6_t":"Legal Audit","out:srv6_d":"Analysis of existing company documentation and elimination of identified deficiencies.","out:footer_address_text":"Tashkent, Yunusabad district, Center 4, Abdulla Qodiriy street 28A","out:footer_rights":"All rights reserved.","lic:lic_title":"Licenses and Permits","lic:lic_desc":"Legal processing of all necessary permits for your business","lic:lic_main_title":"Easy Cooperation with State Bodies","lic:lic_main_desc":"Entrust complex bureaucratic processes to us. We will assist you at all stages of licensing and permitting processes.","lic:srv1_t":"Obtaining a License","lic:srv1_d":"Full legal service for obtaining licenses for various activities. Communication with state bodies and document preparation.","lic:srv2_t":"Permits","lic:srv2_d":"Obtaining permits for construction, import-export, healthcare, and other sectors. We support all processes.","lic:srv3_t":"License Renewal","lic:srv3_d":"Renewing existing licenses and permits and extending their terms. Reminder service for timely renewal.","lic:footer_address_text":"Tashkent, Yunusabad district, Center 4, Abdulla Qodiriy street 28A","lic:footer_rights":"All rights reserved.","ex_hero_eyebrow":"Legal consulting — Tashkent","ex_btn_services":"Our services","ex_stat1":"Practice areas","ex_stat2":"Rapid legal advice","ex_stat3":"Service languages","ex_stat4":"Online — across Uzbekistan","ex_btn_faq":"All questions & answers","ex_label_email":"Email (optional)","ex_form_hint":"Fill in the fields — our specialists will contact you shortly.","msg_fill":"Please enter your name and phone number.","ex_cta_t":"Start resolving your legal matter today","ex_cta_d":"The initial short consultation is free. Reach out in the way that suits you.","ex_side_t":"Have a question?","ex_side_d":"Our specialists will advise you in detail on this practice area.","ex_call":"Call us","ex_write":"Write to us","ex_addr_t":"Address","ex_social_t":"Social media","ex_about_pre":"About us","ex_faq_pre":"Q&A","ex_contact_pre":"Contact","ex_svc_pre":"Services","blog:faq16_q":"Is going to court always necessary to get a divorce?","blog:faq16_a":"No. Where the spouses agree, have no minor children and no property dispute, the marriage is dissolved at the civil registry. Otherwise the case goes to court.","blog:faq17_q":"How long is given to accept an inheritance?","blog:faq17_a":"The certificate of the right to inheritance is issued six months after the inheritance opens; a notary must be approached within that time. A deadline missed for a valid reason can be restored by the court.","blog:faq18_q":"What is required to become an IT Park resident?","blog:faq18_a":"First a legal entity is registered in Uzbekistan, then an application is filed via the official IT Park portal using a digital signature. The activity type must match the permitted list.","ex_process_pre":"Process","ins:ins_title":"Insolvency","ins:ins_desc":"Professional legal assistance on the insolvency of individuals and legal entities","ins:ins_main_title":"A Lawful Way Out of Debt","ins:ins_main_desc":"Insolvency is not the end of a business but a statutory opportunity for a fresh start. We protect the interests of debtors and creditors at every stage of the court procedure under Law No. ZRU-763 of 12 April 2022 on Insolvency.","ins:note_t":"Legal basis","ins:note_d":"Law of the Republic of Uzbekistan No. ZRU-763 of 12 April 2022 on Insolvency, the Economic Procedural Code and the relevant rulings of the Supreme Court Plenum. Every situation is analysed individually and the outcome depends on the circumstances of the case.","ins:srv1_t":"Insolvency of Legal Entities","ins:srv1_d":"Initiating insolvency proceedings against a company and representation in monitoring, judicial rehabilitation, external management and liquidation procedures.","ins:srv2_t":"Insolvency of Individuals","ins:srv2_d":"Preparing a court application regarding bank loans and other personal debts, and developing a debt restructuring plan.","ins:srv3_t":"Protection of Creditors' Interests","ins:srv3_d":"Including claims in the register of creditors, participating in creditors' meetings and building a legal debt recovery strategy.","ins:srv4_t":"Rehabilitation and Settlement","ins:srv4_d":"Preparing a financial recovery plan, negotiating a settlement agreement with creditors and having it approved by the court.","ins:srv5_t":"Challenging Transactions and Liability","ins:srv5_d":"Invalidating a debtor's suspicious transactions and cases on the subsidiary liability of directors and founders.","ins:srv6_t":"Individual Entrepreneurs","ins:srv6_d":"Full legal support for debtors holding individual entrepreneur status, taking into account the specifics of the procedure.","ins:steps_t":"How the Case Is Handled","ins:steps_d":"A clear and transparent four-stage process","ins:step1_t":"Financial Analysis","ins:step1_d":"The debt structure, assets and signs of insolvency are assessed.","ins:step2_t":"Document Preparation","ins:step2_d":"The court application, annexes and evidence base are prepared.","ins:step3_t":"Court Representation","ins:step3_d":"Your interests are protected at every stage of the procedure.","ins:step4_t":"Final Outcome","ins:step4_d":"Debts are restructured or written off and the procedure is completed.","ins:faq_t":"Frequently Asked Questions","ins:faq_d":"The most common questions on insolvency matters","ins:faq1_q":"When can an individual be declared insolvent?","ins:faq1_a":"A court application is possible where the debtor has failed to meet monetary obligations for three months and the debt is at least 200 times the base calculation value. Each case is assessed individually on the basis of the documents.","ins:faq2_q":"What are the signs of insolvency for a legal entity?","ins:faq2_a":"The law provides for two signs: temporary insolvency — failure to perform an obligation within three months (six months for city-forming and equivalent enterprises); and permanent insolvency — the debtor's liabilities exceeding the value of its assets.","ins:faq3_q":"Which procedures are applied?","ins:faq3_a":"For a legal entity: monitoring, judicial rehabilitation, external management, liquidation and a settlement agreement. For an individual: a debt restructuring plan, the sale of property and a settlement agreement.","ins:faq4_q":"Which court hears the case?","ins:faq4_a":"A case against a legal entity is heard by the court at its place of state registration, and against an individual or individual entrepreneur by the court at their place of residence, under the rules of the Economic Procedural Code.","ins:faq5_q":"Is all property seized during the procedure?","ins:faq5_a":"No. The law sets out a list of property exempt from enforcement, which is taken into account during the procedure. Separate rules apply to pledged property, and each case must be analysed individually.","ins:faq6_q":"Is there liability for fictitious insolvency?","ins:faq6_a":"Yes. Deliberate or fictitious insolvency carries administrative and criminal liability. In addition, subsidiary liability may be imposed on the company's director and founders.","fam:fam_title":"Family Law","fam:fam_desc":"Reliable legal assistance on marriage, divorce, alimony, children, property and inheritance","fam:fam_main_title":"A Calm and Fair Resolution of Family Matters","fam:fam_main_desc":"Family disputes are always personal and sensitive. Relying on the Family Code and the Civil Code of the Republic of Uzbekistan, we protect the client's interests and above all those of the children, seeking a pre-trial settlement wherever possible.","fam:note_t":"Legal basis","fam:note_d":"The Family Code, the Civil Code (Section V — Inheritance Law) and the Civil Procedural Code of the Republic of Uzbekistan, together with the Supreme Court Plenum rulings on divorce and inheritance. Advice is given based on the specific circumstances of each family.","fam:srv1_t":"Divorce","fam:srv1_d":"Dissolving a marriage through the civil registry or in court, drafting the statement of claim and representation at hearings.","fam:srv2_t":"Division of Property","fam:srv2_d":"Dividing spouses' joint property, separating personal assets and formalising a division agreement.","fam:srv3_t":"Alimony Matters","fam:srv3_d":"Recovering alimony as a share of income or a fixed sum, changing the amount and collecting arrears.","fam:srv4_t":"Child-Related Disputes","fam:srv4_d":"Determining a child's place of residence, contact arrangements with the other parent, establishing paternity and adoption.","fam:srv5_t":"Inheritance","fam:srv5_d":"Formalising acceptance of an inheritance, restoring missed deadlines, compulsory shares and disputes among heirs.","fam:srv6_t":"Wills and Prenuptial Agreements","fam:srv6_d":"Drafting wills and prenuptial agreements, notarial certification, and proceedings to have them declared invalid.","fam:steps_t":"How We Work","fam:steps_d":"A careful, step-by-step approach to sensitive matters","fam:step1_t":"Confidential Consultation","fam:step1_d":"We listen to your situation, review the documents and explain the realistic prospects.","fam:step2_t":"Pre-Trial Settlement","fam:step2_d":"Where possible, we work towards an agreement between the parties.","fam:step3_t":"Court Protection","fam:step3_d":"If no agreement is reached, a claim is filed and your interests are defended in court.","fam:step4_t":"Formalisation","fam:step4_d":"The decision is formalised at the registry or notary and its enforcement is monitored.","fam:faq_t":"Frequently Asked Questions","fam:faq_d":"The most common questions on family law","fam:faq1_q":"When is a marriage dissolved through the civil registry?","fam:faq1_a":"Where the spouses agree, have no minor children in common and there is no dispute over property or maintenance, the marriage is dissolved at the civil registry. Otherwise the case is heard in court.","fam:faq2_q":"How is the amount of alimony determined?","fam:faq2_a":"Absent an agreement between the parents, the court awards 1/4 of monthly earnings and other income for one child, 1/3 for two and 1/2 for three or more. The amount per child may not be less than 26.5 per cent of the statutory minimum wage.","fam:faq3_q":"How is joint marital property divided?","fam:faq3_a":"Property acquired during the marriage is treated as joint and is usually divided equally. The court may depart from equal shares in the interests of minor children or other relevant circumstances. Property owned before the marriage or received by inheritance or gift is personal property.","fam:faq4_q":"What is the deadline for accepting an inheritance?","fam:faq4_a":"The certificate of the right to inheritance is issued six months after the inheritance opens, and a notary must be approached within that period. If the deadline is missed for a valid reason, it may be restored by the court.","fam:faq5_q":"Is a compulsory share available if there is a will?","fam:faq5_a":"Yes. The testator's minor or incapacitated children, incapacitated spouse and parents are entitled to a compulsory share of the estate regardless of the terms of the will.","fam:faq6_q":"What are the consequences of failing to pay alimony?","fam:faq6_a":"Arrears are collected through enforcement proceedings; the bailiff may restrict property and accounts and temporarily bar travel abroad. Prolonged non-payment may result in administrative and criminal liability.","itp:itp_title":"IT Park Residency","itp:itp_desc":"Resident status, tax incentives and legal structuring of export activity for IT companies","itp:itp_main_title":"A Preferential Legal Environment for Your IT Business","itp:itp_main_desc":"IT Park residency gives technology companies in Uzbekistan substantial tax and customs incentives. We provide support at every stage — from choosing the right activity type to filing the application, signing the agreement and meeting ongoing reporting duties.","itp:note_t":"Important note","itp:note_d":"Incentives are set by the current Tax Code and by presidential decrees and government resolutions governing IT Park, and are updated from time to time. Specific rates, deadlines and the list of permitted activities are verified against the version in force on the date of the request.","itp:srv1_t":"Obtaining Resident Status","itp:srv1_d":"Preparing the business plan, filing the application and concluding the resident activity agreement with the IT Park directorate.","itp:srv2_t":"Company Formation and Activity Type","itp:srv2_d":"Registration as an LLC or another form and correctly selecting the activity code from the list of permitted activities.","itp:srv3_t":"Tax Incentives and Reporting","itp:srv3_d":"Lawful application of incentives, quarterly reporting procedures and advance assessment of tax risks.","itp:srv4_t":"Export and Currency Operations","itp:srv4_d":"Contracts with foreign clients, documenting the export of IT services and advice on currency proceeds.","itp:srv5_t":"IT Visa and Foreign Specialists","itp:srv5_d":"Arranging visas, registration and employment relations for foreign founders and specialists.","itp:srv6_t":"Protection of Software Products","itp:srv6_d":"Securing the IT product through copyright, trademarks, NDAs, licensing and outsourcing agreements.","itp:steps_t":"The Path to Residency","itp:steps_d":"Four stages — from preparation to ongoing support","itp:step1_t":"Activity Assessment","itp:step1_d":"We check whether your business model matches the permitted activity types.","itp:step2_t":"Company Setup","itp:step2_d":"A legal entity is formed or existing documents are brought into compliance.","itp:step3_t":"Application and Agreement","itp:step3_d":"The application is submitted via the portal and the resident agreement is signed.","itp:step4_t":"Ongoing Support","itp:step4_d":"We assist with reporting, contracts and retaining the incentives.","itp:faq_t":"Frequently Asked Questions","itp:faq_d":"The most common questions about IT Park residency","itp:faq1_q":"What tax incentives do residents receive?","itp:faq1_a":"Residents benefit from a zero rate on profit tax, turnover tax and social tax, while employee income tax is 7.5 per cent. Customs incentives also apply to certain equipment imported for the company's own needs. Exact rates and validity periods are verified against the current version of the law.","itp:faq2_q":"Where and how is the application filed?","itp:faq2_a":"Once the company is registered as a legal entity in Uzbekistan, the application is filed online through the official IT Park portal using a digital signature, with a business plan and constitutive documents attached.","itp:faq3_q":"Can any IT company become a resident?","itp:faq3_a":"No. Residency is granted only to companies whose activities fall within the statutory list of permitted activity types. Not every computer- or technology-related business automatically qualifies, so the activity type should be checked in advance.","itp:faq4_q":"Must the company be located in Tashkent?","itp:faq4_a":"No. Resident status and the related incentives apply to companies registered anywhere in Uzbekistan — a physical presence in Tashkent is not required.","itp:faq5_q":"What obligations does a resident have?","itp:faq5_a":"A resident must comply with the obligations under the activity conditions agreement with IT Park and submit quarterly information on its activities. Failure to comply may result in the status and incentives being terminated.","itp:faq6_q":"What opportunities exist for foreign founders and specialists?","itp:faq6_a":"A special visa regime is available for foreign specialists, along with the option to pay dividends and salaries in foreign currency and support programmes for foreign companies. The terms of each programme must be checked separately.","ex_map_open":"Open in Maps","ex_map_route":"Get directions","ex_note_t":"Legal basis","ex_steps_t":"How We Work","ex_steps_d":"Four stages of clear and transparent cooperation","ex_faq_t":"Frequently Asked Questions","ex_faq_d":"The most common questions on this practice area","ex_geo_t":"Our Office","ex_geo_d":"We are located in the Yunusabad district of Tashkent","korp:note_d":"The Civil Code of the Republic of Uzbekistan, the laws on Limited and Additional Liability Companies and on Joint-Stock Companies and Protection of Shareholders' Rights, and the Law on Guarantees of Freedom of Entrepreneurial Activity.","korp:step1_t":"Business Model Analysis","korp:step1_d":"The activity type, legal form and composition of founders are assessed.","korp:step2_t":"Constitutive Documents","korp:step2_d":"The charter, foundation agreement and participants' resolutions are drafted in line with the law.","korp:step3_t":"State Registration","korp:step3_d":"Documents are filed via the public services portal and the certificate is obtained.","korp:step4_t":"Launching Operations","korp:step4_d":"The bank account, digital signature, internal documents and tax registration are arranged.","korp:pfaq1_q":"How long does it take to set up an LLC?","korp:pfaq1_a":"With a complete and correct set of documents, electronic state registration takes from 30 minutes to one working day. Most of the time goes on preparing the documents beforehand.","korp:pfaq2_q":"Is there a minimum charter capital?","korp:pfaq2_a":"No minimum is set by law for a limited liability company — the founders determine it themselves. Special requirements apply to certain licensed activities and to the financial sector.","korp:pfaq3_q":"Can a foreign person found a company?","korp:pfaq3_a":"Yes. Foreign individuals and legal entities may found a company in Uzbekistan. Additional requirements on charter capital and documentation may apply to enterprises with foreign investment.","korp:pfaq4_q":"What is required to replace a director?","korp:pfaq4_a":"A resolution of the participants' (shareholders') meeting is adopted, an employment contract is signed with the new director and the change is entered in the state register. Bank details and the digital signature are also updated.","korp:pfaq5_q":"How long does liquidating a company take?","korp:pfaq5_a":"Voluntary liquidation involves notifying creditors, settling accounts and a tax audit. In practice it takes several months and depends on the scale of the company's obligations.","meh:note_d":"The current Labour Code of the Republic of Uzbekistan, Supreme Court Plenum rulings on labour disputes and government resolutions on remuneration and working time.","meh:step1_t":"HR Document Audit","meh:step1_d":"Employment contracts, orders and internal documents are checked for legal compliance.","meh:step2_t":"Correcting Deficiencies","meh:step2_d":"Identified errors are corrected and missing documents are drafted.","meh:step3_t":"Pre-Trial Settlement","meh:step3_d":"The dispute is addressed through the labour disputes commission or negotiations.","meh:step4_t":"Court Representation","meh:step4_d":"If no agreement is reached, a claim is filed and your interests are defended in court.","meh:pfaq1_q":"What is the maximum probation period?","meh:pfaq1_a":"As a general rule probation does not exceed three months; a longer period may be set for certain categories. The probation clause must be expressly stated in the contract, otherwise the employee is deemed hired without probation.","meh:pfaq2_q":"How much notice must an employee give?","meh:pfaq2_a":"An employee resigning voluntarily must give written notice at least two weeks — 14 calendar days — in advance. By agreement of the parties the contract may be terminated sooner.","meh:pfaq3_q":"Where to turn after an unlawful dismissal?","meh:pfaq3_a":"You may apply to the labour disputes commission or directly to court. A shortened limitation period applies to reinstatement claims, so it is important to consult a lawyer without delay.","meh:pfaq4_q":"Are internal labour regulations mandatory?","meh:pfaq4_a":"Yes. Internal labour regulations, a staffing table and job descriptions must exist in every organisation. Their absence may lead to administrative liability during inspections.","meh:pfaq5_q":"How is remote work documented?","meh:pfaq5_a":"Remote work and part-time arrangements are set out in writing in the employment contract or a supplementary agreement. The rules on recording working time and remuneration must also be clearly stated.","tax:note_d":"The Tax Code of the Republic of Uzbekistan, presidential decrees and government resolutions on tax incentives, and official clarifications issued by the tax authorities.","tax:step1_t":"Tax Position Review","tax:step1_d":"The current tax regime, reporting and existing risks are assessed.","tax:step2_t":"Optimisation Plan","tax:step2_d":"Options for using lawful incentives and regimes are proposed.","tax:step3_t":"Reporting","tax:step3_d":"Declarations and reports are prepared correctly and filed on time.","tax:step4_t":"Audit Defence","tax:step4_d":"Liaison with the tax authorities and, if needed, defence through appeal and in court.","tax:pfaq1_q":"What is the turnover tax rate?","tax:pfaq1_a":"The general rate is 4 per cent. Reduced rates apply to certain regions, activities and categories of business — the exact rate depends on your type of activity.","tax:pfaq2_q":"When does VAT registration become mandatory?","tax:pfaq2_a":"Once annual turnover exceeds the statutory threshold of one billion soums, the company becomes a payer of value added tax and profit tax. Voluntary VAT registration is also possible.","tax:pfaq3_q":"Is advance notice given of a tax audit?","tax:pfaq3_a":"Scheduled audits are carried out in the established manner with prior notice. Separate grounds and procedures apply to prompt and cross-checks.","tax:pfaq4_q":"Can a tax authority decision be appealed?","tax:pfaq4_a":"Yes. A decision may be appealed to a higher tax authority or directly to court. The appeal deadlines must be strictly observed, otherwise the right is lost.","tax:pfaq5_q":"What measures apply to tax arrears?","tax:pfaq5_a":"If arrears are not paid on time, statutory enforcement measures may apply — including suspending account operations and levying on property. Timely action can prevent such consequences.","ip:note_d":"The laws on Trademarks, Service Marks and Appellations of Origin, on Copyright and Related Rights, and on Inventions, Utility Models and Industrial Designs, together with the relevant provisions of the Civil Code.","ip:step1_t":"Preliminary Search","ip:step1_d":"The mark or solution is checked against existing registrations.","ip:step2_t":"Application Preparation","ip:step2_d":"The description, image and classes of goods and services are correctly selected.","ip:step3_t":"Examination","ip:step3_d":"Queries from the competent authority are answered and objections resolved.","ip:step4_t":"Certificate and Protection","ip:step4_d":"The certificate is obtained, its term monitored and action taken against infringements.","ip:pfaq1_q":"How long does trademark registration take?","ip:pfaq1_a":"In the standard procedure the process takes several months and depends on the examination stages. Accelerated examination is available and significantly shortens the timeline.","ip:pfaq2_q":"Is a search required before filing?","ip:pfaq2_a":"It is not formally required, but a prior search identifies similar marks and substantially reduces the risk of refusal and later disputes. We always recommend it.","ip:pfaq3_q":"Does copyright need registration?","ip:pfaq3_a":"Copyright arises upon creation of the work and requires no registration. Voluntary deposit serves as evidence of authorship if a dispute arises.","ip:pfaq4_q":"For how long is a trademark valid?","ip:pfaq4_a":"Trademark rights are granted for ten years and may be renewed for the same term an unlimited number of times. Renewal must be requested before the term expires.","ip:pfaq5_q":"What if someone else uses my mark?","ip:pfaq5_a":"The infringement is first documented and a cease-and-desist letter sent. If that fails, a claim is filed seeking an injunction, withdrawal of counterfeit goods and damages.","out:note_d":"The service is formalised by contract under the Civil Code provisions on paid services. Court representation is carried out in accordance with the Civil, Economic and Administrative Procedure Codes.","out:step1_t":"Legal Audit","out:step1_d":"Existing contracts, internal documents and risks are reviewed in full at the outset.","out:step2_t":"Contract and Tariff","out:step2_d":"A monthly tariff matching the workload is selected and the service agreement is signed.","out:step3_t":"Day-to-Day Support","out:step3_d":"Prompt legal support is provided on contracts, orders and enquiries.","out:step4_t":"Reporting and Improvement","out:step4_d":"A report on the work performed is provided along with proposals to reduce risks.","out:pfaq1_q":"How does outsourcing differ from an in-house lawyer?","out:pfaq1_a":"Instead of one lawyer, a team specialising in corporate, labour, tax and litigation matters is available. There are no salary, payroll tax or holiday costs.","out:pfaq2_q":"For what term is the contract concluded?","out:pfaq2_a":"Usually for one year with monthly payment. A shorter trial term can be agreed; the termination procedure is set out in the document in advance.","out:pfaq3_q":"Who represents you in court?","out:pfaq3_a":"In civil, economic and administrative cases our lawyers act under a power of attorney. Defence in criminal cases may, by law, only be provided by a person holding advocate status.","out:pfaq4_q":"How is confidentiality ensured?","out:pfaq4_a":"A confidentiality clause is included in the contract and a separate NDA signed if required. Documents are shared only with a limited circle of responsible staff and are not disclosed to third parties.","out:pfaq5_q":"Does the fee change if the workload grows?","out:pfaq5_a":"The monthly tariff covers the agreed scope. Additional work such as litigation or major transactions is agreed separately in advance — there are no unexpected charges.","lic:note_d":"Law No. ZRU-701 of 14 July 2021 on Licensing, Permit and Notification Procedures, Presidential Decree No. PF-6044 of 24 August 2020 and the relevant unified regulations of the Cabinet of Ministers.","lic:step1_t":"Identifying the Procedure","lic:step1_d":"We determine whether your activity requires a licence, a permit or a notification.","lic:step2_t":"Meeting the Requirements","lic:step2_d":"Staff, premises, equipment and documents are brought into line with the licence conditions.","lic:step3_t":"Online Filing","lic:step3_d":"The application is filed via the Litsenziya information system or the public services portal.","lic:step4_t":"Monitoring and Renewal","lic:step4_d":"Deadlines are tracked and re-issuance and renewal carried out on time.","lic:pfaq1_q":"What is the difference between a licence, a permit and a notification?","lic:pfaq1_a":"These are three distinct procedures. A licence involves the strictest requirements, a permit is issued under a simpler procedure, and under the notification regime it is enough to notify the competent authority before starting.","lic:pfaq2_q":"Where is the application submitted?","lic:pfaq2_a":"The application is filed online through the Litsenziya information system or the Unified Portal of Interactive Public Services using a digital signature.","lic:pfaq3_q":"What are the grounds for refusing a licence?","lic:pfaq3_a":"The law provides three main grounds: incomplete submission of documents; the applicant's failure to meet the licence requirements and conditions; and inaccurate or distorted information in the documents submitted.","lic:pfaq4_q":"Can a refusal be appealed?","lic:pfaq4_a":"Yes. The applicant is entitled to appeal the licensing authority's decision and the actions or inaction of its officials directly to court in the established manner.","lic:pfaq5_q":"What happens when the term expires?","lic:pfaq5_a":"Continuing to operate under an expired licence is unlawful and entails liability. An application for renewal should therefore be made before the term expires."}};